// Banco de prompts de diseño para la Galería de diseño. Cada item define un sector, un tipo
// de layout (para elegir la miniatura wireframe), nombre, descripción y el prompt detallado.
// Generado con agentes en paralelo; se puede ampliar libremente.

export type LayoutDiseno =
  | "hero"
  | "dashboard"
  | "mobile"
  | "cards3"
  | "grid"
  | "split"
  | "form"
  | "list"
  | "chat"
  | "scene3d"

export type PlantillaDiseno = {
  sector: string
  layout: LayoutDiseno
  nombre: string
  descripcion: string
  prompt: string
}

export const PLANTILLAS_DISENO: PlantillaDiseno[] = [
  { sector: "Web", layout: "hero", nombre: "Nova Analytics SaaS", descripcion: "Dashboard B2B con hero centrado", prompt: "Landing para SaaS de analítica B2B llamado Nova. Estilo moderno tech, fondo blanco con gradientes sutiles violeta-índigo (#6D5EF6 a #8B7CFF), tipografía sans geométrica (Inter). Hero centrado con titular grande, badge 'Nuevo: IA integrada', doble CTA y captura de dashboard flotante con sombra suave. Entregable: HTML + CSS con hero, logos de clientes, grid de features y footer." },
  { sector: "Web", layout: "split", nombre: "Estudio Kora Creativo", descripcion: "Agencia con split editorial audaz", prompt: "Landing para agencia creativa Kora. Estilo editorial atrevido, fondo negro carbón (#0A0A0A) con acentos coral vibrante (#FF5A3C) y tipografía serif display enorme mezclada con mono. Layout split: mitad izquierda titular gigante rotado, mitad derecha imagen de proyecto a sangre. Entregable: HTML + CSS con split hero, cinta de servicios en marquesina y bloque de contacto." },
  { sector: "Web", layout: "hero", nombre: "Sazón Restaurante", descripcion: "Alta cocina con hero fotográfico", prompt: "Landing para restaurante de alta cocina Sazón. Estilo elegante gastronómico, foto de plato a pantalla completa oscurecida, tipografía serif fina dorada (#C9A227) sobre negro profundo. Hero con reserva integrada, horario y frase del chef. Entregable: HTML + CSS con hero fotográfico, sección de menú degustación en dos columnas y bloque de reservas con formulario." },
  { sector: "Web", layout: "grid", nombre: "Trama Moda Store", descripcion: "Ecommerce moda con grilla de productos", prompt: "Landing ecommerce de moda urbana Trama. Estilo limpio minimal fashion, fondo crema (#F4F1EC), acentos negro y verde oliva, tipografía sans condensada. Grid de productos tipo lookbook con hover que muestra segundo ángulo y precio. Entregable: HTML + CSS con barra superior, grid responsive de 6 productos, banner de colección y newsletter." },
  { sector: "Web", layout: "hero", nombre: "Pulse Fitness Club", descripcion: "Gimnasio con hero energético", prompt: "Landing para gimnasio Pulse. Estilo dinámico y potente, fondo negro con acentos amarillo neón (#D9FF3C) y magenta, tipografía bold itálica. Hero con foto de atleta en movimiento, contador de miembros y CTA 'Primera semana gratis'. Entregable: HTML + CSS con hero energético, tarjetas de planes de membresía, horarios de clases y testimonios." },
  { sector: "Web", layout: "split", nombre: "Altura Inmobiliaria", descripcion: "Bienes raíces de lujo en split", prompt: "Landing inmobiliaria de lujo Altura. Estilo sofisticado y sereno, paleta beige arena, blanco y azul pizarra (#2E3A45), tipografía serif elegante. Split: izquierda datos de la propiedad y CTA de visita, derecha render arquitectónico a sangre con precio superpuesto. Entregable: HTML + CSS con split hero, listado destacado de propiedades y formulario de agenda de visita." },
  { sector: "Web", layout: "hero", nombre: "Vértice Conf Tech", descripcion: "Evento tech con hero countdown", prompt: "Landing para conferencia tecnológica Vértice 2026. Estilo futurista con gradiente cian-morado sobre fondo azul noche (#0B1026), grid de puntos y glow, tipografía sans futurista. Hero con nombre del evento, fecha, cuenta regresiva animada y CTA de entradas. Entregable: HTML + CSS con hero countdown, grid de speakers, agenda por días y bloque de sponsors." },
  { sector: "Web", layout: "split", nombre: "Raíz ONG Ambiental", descripcion: "ONG verde con split de impacto", prompt: "Landing para ONG ambiental Raíz. Estilo cálido y esperanzador, paleta verde bosque (#2F6B3C), tierra y crema, tipografía humanista redondeada. Split: izquierda mensaje de misión con CTA 'Donar', derecha foto de reforestación con contador de árboles plantados. Entregable: HTML + CSS con split hero, métricas de impacto, historias y formulario de donación." },
  { sector: "Web", layout: "hero", nombre: "Flow App Showcase", descripcion: "App móvil con mockup flotante", prompt: "Landing showcase de app móvil de productividad Flow. Estilo Apple-like premium, fondo blanco con degradado gris perla, acentos azul eléctrico (#2D7FF9), tipografía sans limpia. Hero centrado con dos mockups de iPhone flotando en ángulo y badges de App Store. Entregable: HTML + CSS con hero de mockups, features alternadas con capturas y sección de descarga." },
  { sector: "Web", layout: "hero", nombre: "Nexo Neobanco", descripcion: "Fintech con hero de tarjeta 3D", prompt: "Landing para neobanco Nexo. Estilo fintech moderno y confiable, fondo azul profundo (#0E2A47) con gradiente aqua, tipografía sans redondeada. Hero con tarjeta bancaria flotante en 3D con reflejos, titular sobre finanzas sin comisiones y CTA 'Abrir cuenta'. Entregable: HTML + CSS con hero de tarjeta, features de seguridad, comparativa de planes y sellos de confianza." },
  { sector: "Web", layout: "grid", nombre: "Saber Cursos Online", descripcion: "Edtech con grilla de cursos", prompt: "Landing para plataforma de cursos online Saber. Estilo amigable educativo, paleta índigo (#4B44C4), amarillo y blanco, tipografía sans clara con ilustraciones planas. Grid de tarjetas de cursos con categoría, duración, nivel y rating por estrellas. Entregable: HTML + CSS con hero breve, buscador, grid de 6 cursos, barra de categorías y CTA de prueba gratis." },
  { sector: "Web", layout: "split", nombre: "Sonrisa Clínica Dental", descripcion: "Salud dental con split confiable", prompt: "Landing para clínica dental Sonrisa. Estilo salud limpio y cálido, paleta blanco, celeste suave (#5BC5D6) y menta, tipografía sans amable. Split: izquierda titular tranquilizador con CTA 'Agendar turno', derecha foto de paciente sonriendo. Entregable: HTML + CSS con split hero, tarjetas de tratamientos, equipo de dentistas y formulario de turno." },
  { sector: "Web", layout: "grid", nombre: "Rumbo Viajes", descripcion: "Agencia de viajes con grilla de destinos", prompt: "Landing para agencia de viajes Rumbo. Estilo aventurero y vívido, paleta turquesa (#12A9A0), coral y arena, tipografía sans con acentos manuscritos. Grid tipo mosaico de destinos con fotos, precio 'desde' y etiqueta de temporada. Entregable: HTML + CSS con hero de búsqueda de viaje, grid de 6 destinos, ofertas destacadas y newsletter." },
  { sector: "Web", layout: "hero", nombre: "Eco Artista Musical", descripcion: "Músico con hero inmersivo oscuro", prompt: "Landing para artista musical Eco lanzando álbum. Estilo inmersivo y artístico, fondo negro con degradado púrpura-azul y textura de grano, tipografía display condensada. Hero con portada del álbum, botón de reproducir y enlaces a plataformas de streaming. Entregable: HTML + CSS con hero del álbum, reproductor de tracklist, próximas fechas de gira y footer social." },
  { sector: "Web", layout: "hero", nombre: "Nebula Game Studio", descripcion: "Estudio gaming con hero cinemático", prompt: "Landing para estudio de videojuegos Nebula presentando su título. Estilo gamer cinemático, fondo espacial oscuro con neón cian y rojo, glow y partículas, tipografía tech angular. Hero con key art a sangre, logo del juego, tráiler embebido y CTA 'Añadir a lista de deseos'. Entregable: HTML + CSS con hero cinemático, galería de screenshots, features del juego y plataformas." },
  { sector: "Web", layout: "hero", nombre: "Ledger Crypto Exchange", descripcion: "Exchange cripto con hero de datos", prompt: "Landing para exchange de criptomonedas Ledger. Estilo cripto premium oscuro, fondo negro azulado (#0C0F1A) con acentos verde menta (#00E5A0) y glow, tipografía mono-sans. Hero con titular de trading, ticker de precios en vivo simulado y CTA 'Comprar cripto'. Entregable: HTML + CSS con hero de ticker, features de seguridad, tabla de monedas y sellos regulatorios." },
  { sector: "Web", layout: "split", nombre: "DevForge Herramienta", descripcion: "Dev tool con split terminal oscuro", prompt: "Landing para herramienta de desarrolladores DevForge. Estilo developer oscuro, fondo casi negro (#0D1117), acentos verde terminal (#3FB950) y violeta, tipografía monoespaciada. Split: izquierda titular técnico con CTA 'Instalar' y comando copiable, derecha ventana de terminal con código coloreado. Entregable: HTML + CSS con split hero, bloque de features, snippet de código y estrellas de GitHub." },
  { sector: "Web", layout: "grid", nombre: "Blanco Estudio Branding", descripcion: "Agencia branding minimal en grid", prompt: "Landing para estudio de branding minimalista Blanco. Estilo suizo ultra-minimal, fondo blanco puro, negro y un solo acento rojo (#FF3B30), muchísimo espacio en blanco, tipografía grotesque grande. Grid asimétrico de casos de estudio con número, cliente y año. Entregable: HTML + CSS con hero tipográfico, grid de proyectos, lista de servicios y contacto sobrio." },
  { sector: "Web", layout: "hero", nombre: "Ramen Ya Street Food", descripcion: "Ramen bar con hero vibrante", prompt: "Landing para ramen bar Ramen Ya. Estilo street food japonés vibrante, paleta rojo lacado (#D6262C), crema y negro, tipografía display con toques kanji e ilustración de tazón humeante. Hero con foto cenital de ramen, CTA 'Pedir online' y horario. Entregable: HTML + CSS con hero apetitoso, menú de bowls en tarjetas, ubicación con mapa y sección de pedido." },
  { sector: "Web", layout: "split", nombre: "Nórdica Muebles", descripcion: "Ecommerce deco en split cálido", prompt: "Landing ecommerce de muebles y deco Nórdica. Estilo escandinavo cálido, paleta madera clara, blanco roto y verde salvia (#8FA68E), tipografía serif suave. Split: izquierda producto destacado con precio y CTA 'Comprar', derecha foto de ambiente de interior luminoso. Entregable: HTML + CSS con split hero, grid de productos, banner de envío gratis y newsletter." },
  { sector: "Web", layout: "hero", nombre: "Zen Estudio Yoga", descripcion: "Yoga y wellness con hero sereno", prompt: "Landing para estudio de yoga Zen. Estilo calmo y orgánico, paleta terracota (#C77B58), crema y verde oliva, formas curvas y tipografía serif ligera. Hero sereno con foto de práctica al amanecer, frase inspiradora y CTA 'Reservá tu clase'. Entregable: HTML + CSS con hero suave, tipos de clases, horarios semanales y planes de suscripción." },
  { sector: "Web", layout: "grid", nombre: "Hub Coworking", descripcion: "Coworking con grilla de espacios", prompt: "Landing para espacio de coworking Hub. Estilo urbano fresco, paleta naranja cálido (#FF7A29), gris grafito y blanco, tipografía sans moderna. Grid de tipos de espacio (hot desk, oficina privada, sala de reuniones) con foto, precio y capacidad. Entregable: HTML + CSS con hero, grid de espacios, amenidades con íconos y formulario de tour." },
  { sector: "Web", layout: "split", nombre: "Onda Podcast", descripcion: "Podcast con split de episodio", prompt: "Landing para podcast Onda. Estilo retro-moderno cálido, paleta mostaza (#E8A33D), granate y crema, tipografía display redonda con textura. Split: izquierda titular del show con CTA de suscripción y plataformas, derecha portada del último episodio con botón de play. Entregable: HTML + CSS con split hero, lista de episodios recientes, bio de hosts y suscripción." },
  { sector: "Web", layout: "hero", nombre: "Cognita Startup IA", descripcion: "Startup IA con hero de gradiente", prompt: "Landing para startup de IA Cognita. Estilo futurista suave, fondo blanco con gradiente aurora rosa-violeta-cian y mesh blur, tipografía sans moderna. Hero centrado con titular sobre automatización inteligente, campo de email y CTA 'Solicitar acceso'. Entregable: HTML + CSS con hero mesh, bloque de casos de uso, logos de respaldo y sección de waitlist." },
  { sector: "Web", layout: "hero", nombre: "Grano Café de Especialidad", descripcion: "Cafetería con hero artesanal", prompt: "Landing para cafetería de especialidad Grano. Estilo artesanal cálido, paleta marrón café (#4A2E1E), crema y cobre, tipografía serif vintage con detalles manuscritos. Hero con foto de latte art, frase sobre origen del grano y CTA 'Visitanos'. Entregable: HTML + CSS con hero, sección de granos de origen, menú de bebidas y ubicación con horarios." },
  { sector: "Web", layout: "split", nombre: "Filo Barbería", descripcion: "Barbería con split clásico oscuro", prompt: "Landing para barbería Filo. Estilo vintage masculino, paleta negro, cuero marrón (#6B4226) y dorado envejecido, tipografía slab serif con emblema. Split: izquierda titular y CTA 'Reservá tu corte', derecha foto en blanco y negro de corte clásico. Entregable: HTML + CSS con split hero, lista de servicios con precios, galería de estilos y booking." },
  { sector: "Web", layout: "hero", nombre: "Enlace Wedding Planner", descripcion: "Bodas con hero elegante floral", prompt: "Landing para wedding planner Enlace. Estilo romántico elegante, paleta blush rosa (#E8C8C8), verde eucalipto y dorado, tipografía script caligráfica con serif fina. Hero con foto de boda soñada, frase emotiva y CTA 'Planeá tu día'. Entregable: HTML + CSS con hero floral, servicios de planificación, galería de bodas reales y formulario de consulta." },
  { sector: "Web", layout: "grid", nombre: "Luz Fotografía Portfolio", descripcion: "Fotógrafo con grilla de portfolio", prompt: "Landing portfolio de fotógrafo Luz. Estilo minimal galería, fondo blanco casi total, negro y foco absoluto en la imagen, tipografía sans fina espaciada. Grid tipo masonry de fotografías a alta resolución con hover que revela título y categoría. Entregable: HTML + CSS con hero minimal, grid masonry de 8 fotos, bloque sobre mí y contacto." },
  { sector: "Web", layout: "split", nombre: "Capital Robo-Advisor", descripcion: "Inversiones con split de gráfico", prompt: "Landing para plataforma de inversiones automatizadas Capital. Estilo fintech confiable y sobrio, paleta azul marino (#12294D), verde crecimiento (#1DB981) y blanco, tipografía sans precisa. Split: izquierda titular sobre invertir en piloto automático y CTA 'Empezá a invertir', derecha gráfico de rendimiento ascendente. Entregable: HTML + CSS con split hero, pasos de cómo funciona, comparativa de carteras y sellos de seguridad." },
  { sector: "Web", layout: "hero", nombre: "Stream Plataforma Video", descripcion: "Streaming con hero de catálogo", prompt: "Landing para plataforma de streaming Stream. Estilo entretenimiento premium oscuro, fondo negro con degradado rojo intenso (#E50914), tipografía sans bold. Hero con titular sobre contenido ilimitado, CTA 'Probá gratis' y carrusel de portadas al pie con desvanecido. Entregable: HTML + CSS con hero de catálogo, fila de destacados, planes de suscripción y FAQ." },
  { sector: "Web", layout: "split", nombre: "Aura Spa Estético", descripcion: "Spa estético con split lujoso", prompt: "Landing para spa y clínica estética Aura. Estilo lujo relajante, paleta nude rosado (#E3C9BE), champagne y gris cálido, tipografía serif refinada con mucho aire. Split: izquierda titular sobre bienestar con CTA 'Reservá tu sesión', derecha foto de tratamiento facial sereno. Entregable: HTML + CSS con split hero, menú de tratamientos, testimonios y formulario de reserva." },
  { sector: "Web", layout: "hero", nombre: "Brillo Joyería", descripcion: "Joyería con hero minimalista premium", prompt: "Landing ecommerce de joyería Brillo. Estilo lujo minimalista, fondo negro profundo con acentos dorados (#D4AF37) y tipografía serif delgada elegante. Hero centrado con pieza de joyería en primer plano sobre fondo oscuro, titular sobre elegancia atemporal y CTA 'Ver colección'. Entregable: HTML + CSS con hero de producto, grid de piezas destacadas, historia de marca y newsletter." },
  { sector: "Web", layout: "grid", nombre: "Código Bootcamp", descripcion: "Bootcamp de programación en grid", prompt: "Landing para bootcamp de programación Código. Estilo tech juvenil enérgico, paleta violeta eléctrico (#7C3AED), lima y gris oscuro, tipografía sans bold con acentos mono. Grid de programas (Full Stack, Data, UX) con duración, modalidad y tasa de empleabilidad. Entregable: HTML + CSS con hero de conversión, grid de programas, línea de tiempo del curso, testimonios de egresados y CTA de inscripción." },
  { sector: "Web", layout: "hero", nombre: "Talento Marketplace Freelance", descripcion: "Marketplace freelance con hero dual", prompt: "Landing para marketplace de freelancers Talento. Estilo marketplace fresco y confiable, paleta azul brillante (#2563EB), naranja acento y blanco, tipografía sans clara. Hero con titular dual (contratar / trabajar), buscador de servicios con categorías y prueba social de proyectos completados. Entregable: HTML + CSS con hero de buscador, categorías populares en tarjetas, cómo funciona en pasos y CTA doble." },
  { sector: "Web", layout: "dashboard", nombre: "Analítica SaaS Nébula", descripcion: "Panel de métricas para producto SaaS", prompt: "Diseñá un dashboard de analítica web para una plataforma SaaS B2B, estilo moderno minimalista con dark mode profundo (fondo #0B0F1A, superficies #151A28) y acentos violeta eléctrico (#7C5CFF) y cian (#22D3EE). Sidebar vertical colapsable a la izquierda, top bar con selector de rango de fechas. Fila superior de 4 KPIs (MRR, usuarios activos, churn, conversión) con sparklines. Gráfico de área grande de sesiones en el tiempo, barras de fuentes de tráfico y tabla de páginas top. Entregable: HTML + CSS con CSS Grid, tipografía Inter." },
  { sector: "Web", layout: "dashboard", nombre: "CRM Ventas Meridian", descripcion: "Pipeline comercial B2B tipo Kanban", prompt: "Diseñá un dashboard CRM de ventas B2B con estética corporativa clara (fondo #F7F8FB, tarjetas blancas, sombras suaves) y acento azul índigo (#3355FF) con verde éxito (#16A34A). Header con embudo de pipeline horizontal por etapa, KPIs de deals cerrados, valor de cartera y tasa de cierre. Cuerpo dividido: tablero Kanban de oportunidades con avatares y montos a la izquierda, panel de actividad reciente y tareas del día a la derecha. Entregable: HTML + CSS con flexbox y grid, componentes de tarjeta reutilizables." },
  { sector: "Web", layout: "dashboard", nombre: "Finanzas Personales Pluma", descripcion: "Panel de presupuesto y gastos personales", prompt: "Diseñá un dashboard de finanzas personales cálido y amigable, fondo crema (#FBF7F0), acentos coral (#FF6B5E) y verde menta (#2FBF9E), esquinas muy redondeadas. Tarjeta de balance total destacada arriba con degradado suave. Donut de gastos por categoría, barra de progreso de presupuesto mensual, lista de transacciones recientes con íconos por comercio, y gráfico de línea de ahorro proyectado. Entregable: HTML + CSS, layout responsive con grid, tipografía redondeada tipo Nunito." },
  { sector: "Web", layout: "dashboard", nombre: "Salud Hospital Vitalis", descripcion: "Panel clínico de camas y pacientes", prompt: "Diseñá un dashboard de administración hospitalaria, estilo limpio y confiable con fondo blanco clínico, azul médico (#0E7490) y acentos de estado (verde estable, ámbar observación, rojo crítico). Header con ocupación de camas total y turno actual. Grilla de salas con estado por color, gráfico de admisiones/altas del día, lista de pacientes prioritarios con signos vitales, y panel de disponibilidad de personal. Entregable: HTML + CSS con grid, íconos médicos y badges de estado accesibles." },
  { sector: "Web", layout: "dashboard", nombre: "Social Pulse Manager", descripcion: "Analítica multired para community manager", prompt: "Diseñá un dashboard de gestión de redes sociales para un community manager, estilo vibrante con dark UI (#12101C) y degradados de marca por red (rosa Instagram, azul cielo, negro X). KPIs de seguidores, alcance, engagement y menciones. Gráfico de crecimiento comparado por plataforma, heatmap de mejores horas para publicar, cola de posts programados en calendario compacto, y top posts con miniaturas. Entregable: HTML + CSS con grid, chips por red social y micro-visualizaciones." },
  { sector: "Web", layout: "dashboard", nombre: "E-commerce Bazar Admin", descripcion: "Panel de ventas y órdenes de tienda", prompt: "Diseñá un dashboard admin de e-commerce para una tienda de moda, estético y editorial con fondo gris muy claro (#F4F4F5), negro carbón y acento fucsia (#EC4899). Header con ingresos del día, órdenes, ticket promedio y stock bajo. Gráfico de ventas por hora, barras de productos más vendidos con thumbnails, mapa de calor de regiones, y tabla de últimas órdenes con estado de envío. Entregable: HTML + CSS con grid, tabla estilizada y badges de estado." },
  { sector: "Web", layout: "dashboard", nombre: "Logística FlotaViva", descripcion: "Monitor de flota y entregas en tiempo real", prompt: "Diseñá un dashboard de logística y última milla, estilo control-room oscuro (#0A0E14) con acento ámbar (#F59E0B) y cian de rutas. Panel principal con mapa estilizado de rutas activas y pines de vehículos, KPIs de entregas a tiempo, en tránsito y demoradas. Lista lateral de conductores con progreso de ruta, gráfico de rendimiento por zona, y timeline de incidencias. Entregable: HTML + CSS con grid, mapa como SVG placeholder e indicadores de estado en vivo." },
  { sector: "Web", layout: "dashboard", nombre: "Soporte Helpdesk Aria", descripcion: "Cola de tickets y SLA de soporte", prompt: "Diseñá un dashboard de soporte al cliente / helpdesk, estilo sobrio y funcional con fondo claro (#FAFAFA), azul acero (#2563EB) y semáforo de SLA (verde/ámbar/rojo). Header con tickets abiertos, tiempo medio de respuesta, CSAT y SLA en riesgo. Cola de tickets priorizada con avatares y etiquetas, gráfico de volumen por canal, gauge de cumplimiento de SLA, y ranking de agentes. Entregable: HTML + CSS con grid, tabla densa y badges de prioridad." },
  { sector: "Web", layout: "dashboard", nombre: "IoT Casa Domótica", descripcion: "Panel de hogar inteligente conectado", prompt: "Diseñá un dashboard de hogar inteligente (IoT), estilo glassmorphism con fondo degradado nocturno azul-morado y tarjetas translúcidas con blur. Tiles por habitación con temperatura, luces y consumo. Termostato circular central, gráfico de consumo energético del día, estado de dispositivos conectados con toggles, y alertas de seguridad. Entregable: HTML + CSS con grid, efecto glass mediante backdrop-filter y controles tipo switch." },
  { sector: "Web", layout: "dashboard", nombre: "Marketing Growth Cohete", descripcion: "Rendimiento de campañas multicanal", prompt: "Diseñá un dashboard de marketing de performance, estilo energético con fondo oscuro (#111827) y acentos naranja (#FB923C) y verde lima. Header con ROAS, CTR, CPA y presupuesto gastado. Gráfico de conversiones por canal (Meta, Google, TikTok), funnel de adquisición vertical, tabla de campañas activas con métricas y semáforo de rendimiento, y anillo de distribución de presupuesto. Entregable: HTML + CSS con grid, funnel en CSS y chips de canal." },
  { sector: "Web", layout: "dashboard", nombre: "Product Analytics Prisma", descripcion: "Métricas de producto y retención", prompt: "Diseñá un dashboard de analítica de producto tipo Mixpanel/Amplitude, estilo tech limpio con fondo blanco, gris pizarra y acento púrpura (#8B5CF6). KPIs de DAU/MAU, stickiness, retención D7 y eventos clave. Curva de retención por cohorte (matriz de colores), gráfico de embudo de activación, gráfico de eventos en el tiempo y segmentos de usuarios. Entregable: HTML + CSS con grid, matriz de cohortes con celdas coloreadas por intensidad." },
  { sector: "Web", layout: "dashboard", nombre: "CRM Inmobiliario Domus", descripcion: "Gestión de propiedades y leads", prompt: "Diseñá un dashboard CRM inmobiliario, estilo elegante con fondo marfil (#FAF8F5), verde bosque (#166534) y dorado suave. Header con propiedades activas, leads nuevos, visitas agendadas y cierres del mes. Galería de propiedades destacadas con foto placeholder y precio, embudo de leads por etapa, mapa de zonas con demanda, y agenda de visitas del día. Entregable: HTML + CSS con grid, tarjetas de propiedad con imagen y layout editorial." },
  { sector: "Web", layout: "dashboard", nombre: "Fintech Neobanco Cifra", descripcion: "Panel de banca digital y transacciones", prompt: "Diseñá un dashboard de neobanco / fintech, estilo premium con fondo negro azabache (#08090D), tarjetas oscuras y acento verde neón (#00E599) tipo tarjeta digital. Balance de cuenta con degradado, KPIs de ingresos, egresos y ahorro. Gráfico de flujo de caja entrada/salida, tarjeta virtual visual, lista de transacciones con categorías e íconos, y desglose de gastos en donut. Entregable: HTML + CSS con grid, estética glossy y microdetalles de tarjeta." },
  { sector: "Web", layout: "dashboard", nombre: "Salud Wearable Latido", descripcion: "Panel de fitness y biometría", prompt: "Diseñá un dashboard de salud y fitness conectado a wearables, estilo deportivo con dark UI (#0D1117) y anillos de actividad estilo Apple (rojo, verde, azul). Anillos de progreso diario centrales, KPIs de pasos, calorías, frecuencia cardíaca y sueño. Gráfico de ritmo cardíaco del día, barras de actividad semanal, fases de sueño en área apilada, y racha de entrenamientos. Entregable: HTML + CSS con grid, anillos concéntricos en SVG y microtipografía." },
  { sector: "Web", layout: "dashboard", nombre: "Streaming Media Onda", descripcion: "Analítica de audiencia de video", prompt: "Diseñá un dashboard de analítica para una plataforma de streaming de video, estilo cine oscuro (#101014) con acento rojo (#EF4444) y púrpura. Header con horas vistas, suscriptores, retención media y contenido top. Gráfico de reproducciones por hora, curva de retención de un episodio, ranking de títulos con thumbnails, y mapa mundial de audiencia. Entregable: HTML + CSS con grid, tarjetas de contenido con carátula placeholder y gráficos de línea." },
  { sector: "Web", layout: "dashboard", nombre: "Marketplace Multivendedor Ágora", descripcion: "Admin de vendedores y comisiones", prompt: "Diseñá un dashboard admin de marketplace multivendedor, estilo neutro profesional con fondo #F5F6F8, azul marino (#1E3A8A) y acento teal. Header con GMV, comisiones, vendedores activos y órdenes. Ranking de vendedores top con rating, gráfico de GMV por categoría, tabla de payouts pendientes, y gráfico de crecimiento de vendedores. Entregable: HTML + CSS con grid, tabla financiera densa y badges de estado de vendedor." },
  { sector: "Web", layout: "dashboard", nombre: "Almacén Inventario Nexo", descripcion: "Control de stock y warehouse", prompt: "Diseñá un dashboard de gestión de inventario / warehouse, estilo industrial claro con fondo #EEF1F4, gris grafito y acento naranja seguridad (#EA580C). KPIs de SKUs, stock total, en tránsito y bajo mínimo. Mapa de ocupación de estanterías tipo grilla, gráfico de rotación de inventario, alertas de reposición, y tabla de movimientos entrada/salida. Entregable: HTML + CSS con grid, visual de bins/estanterías en CSS y semáforos de stock." },
  { sector: "Web", layout: "dashboard", nombre: "Call Center Voz Eco", descripcion: "Monitor de contact center en vivo", prompt: "Diseñá un dashboard de contact center / call center, estilo control operativo oscuro (#0F1420) con acento verde (#22C55E) y ámbar de espera. Header con llamadas activas, en cola, tiempo medio de atención y nivel de servicio. Gauge grande de nivel de servicio, gráfico de volumen de llamadas por hora, lista de agentes con estado (en llamada, disponible, pausa), y distribución de motivos de contacto. Entregable: HTML + CSS con grid, gauge en SVG e indicadores de agente en tiempo real." },
  { sector: "Web", layout: "dashboard", nombre: "IoT Industrial Forja", descripcion: "Monitor de planta y sensores", prompt: "Diseñá un dashboard de IoT industrial / monitoreo de planta, estilo SCADA moderno oscuro (#0A0F16) con acento cian (#06B6D4) y rojo de alarma. Header con OEE, disponibilidad, rendimiento y calidad. Diagrama esquemático de línea de producción con nodos de máquina, gráficos de telemetría (temperatura, vibración, presión) en tiempo real, lista de alarmas activas, y gauges de sensores. Entregable: HTML + CSS con grid, esquema de planta en SVG y sparklines de sensor." },
  { sector: "Web", layout: "dashboard", nombre: "SEO Ranker Cima", descripcion: "Panel de posicionamiento y tráfico orgánico", prompt: "Diseñá un dashboard de SEO, estilo data-driven claro con fondo blanco, verde esmeralda (#059669) y azul. Header con tráfico orgánico, keywords en top 10, autoridad de dominio y backlinks. Gráfico de evolución de posiciones, tabla de keywords con variación de ranking (flechas arriba/abajo), distribución de tráfico por landing, y barras de salud técnica del sitio. Entregable: HTML + CSS con grid, tabla con indicadores de tendencia y micrográficos." },
  { sector: "Web", layout: "dashboard", nombre: "Trading Desk Bolsa", descripcion: "Panel financiero de mercados y cartera", prompt: "Diseñá un dashboard de trading / mercados financieros, estilo terminal profesional negro (#0B0B0F) con verde alza (#22C55E) y rojo baja (#EF4444), tipografía monoespaciada para cifras. Header con valor de cartera, P&L diario y exposición. Gráfico de velas de un activo, watchlist con precios y variación en vivo, distribución de portafolio en donut, y libro de órdenes compacto. Entregable: HTML + CSS con grid, candlestick en SVG y tabla de cotizaciones densa." },
  { sector: "Web", layout: "dashboard", nombre: "LMS Educativo Saber", descripcion: "Admin de cursos y estudiantes", prompt: "Diseñá un dashboard de administración de una plataforma educativa / LMS, estilo amigable con fondo #F6F5FF, violeta suave (#6D5AE6) y amarillo cálido. Header con estudiantes activos, cursos, tasa de finalización y horas de estudio. Gráfico de progreso por curso, ranking de cursos populares con miniaturas, embudo de inscripción a certificación, y lista de estudiantes en riesgo de abandono. Entregable: HTML + CSS con grid, barras de progreso y tarjetas de curso." },
  { sector: "Web", layout: "dashboard", nombre: "Smart Grid Energía Voltia", descripcion: "Monitor de consumo y generación energética", prompt: "Diseñá un dashboard de gestión energética / smart grid, estilo sostenible oscuro (#0C1512) con verde energía (#34D399) y amarillo solar. Header con generación total, consumo, autoconsumo y CO2 evitado. Gráfico de flujo generación vs consumo del día, medidor circular de mix renovable, distribución por fuente (solar, eólica, red), y tabla de subestaciones con carga. Entregable: HTML + CSS con grid, gráfico de área apilada y gauge de mix energético." },
  { sector: "Web", layout: "dashboard", nombre: "Clínica Bienestar Mente", descripcion: "Panel de gestión de salud mental", prompt: "Diseñá un dashboard para una clínica de salud mental / psicología, estilo sereno y cálido con fondo #F5F3EF, verde salvia (#7C9A82) y terracota suave. Header con pacientes activos, sesiones de la semana, adherencia y bienestar promedio. Agenda de sesiones del día, gráfico de evolución de ánimo de pacientes, distribución por tipo de terapia, y lista de seguimientos pendientes. Entregable: HTML + CSS con grid, tipografía humanista y visuales de baja saturación." },
  { sector: "Web", layout: "dashboard", nombre: "Influencer Insights Brillo", descripcion: "Analítica de creador de contenido", prompt: "Diseñá un dashboard de analítica para un influencer / creador, estilo pop con dark UI (#14101F) y degradado magenta-naranja vibrante. Header con seguidores, tasa de engagement, alcance e ingresos por marca. Gráfico de crecimiento de audiencia, demografía de audiencia (edad y género en barras), reels/posts top con miniaturas y métricas, y calendario de colaboraciones. Entregable: HTML + CSS con grid, tarjetas de contenido con thumbnail y gráficos vibrantes." },
  { sector: "Web", layout: "dashboard", nombre: "Restaurante POS Sabor", descripcion: "Panel de ventas y operación gastronómica", prompt: "Diseñá un dashboard de administración de restaurante / POS, estilo apetitoso con fondo #FFF9F2, rojo tomate (#DC2626) y verde albahaca. Header con ventas del día, tickets, ticket promedio y mesas ocupadas. Mapa de salón con estado de mesas, ranking de platos más vendidos, gráfico de ventas por franja horaria, y estado de pedidos en cocina. Entregable: HTML + CSS con grid, plano de mesas en CSS y tarjetas de platos." },
  { sector: "Web", layout: "dashboard", nombre: "People Analytics RRHH Talento", descripcion: "Panel de recursos humanos y plantilla", prompt: "Diseñá un dashboard de RRHH / people analytics, estilo corporativo humano con fondo #F4F6F9, azul confianza (#2563EB) y acento coral. Header con headcount, rotación, tiempo de contratación y eNPS. Gráfico de plantilla por departamento, embudo de reclutamiento, distribución de diversidad, y ranking de razones de baja. Entregable: HTML + CSS con grid, organigrama compacto y barras horizontales." },
  { sector: "Web", layout: "dashboard", nombre: "Ciberseguridad SOC Escudo", descripcion: "Centro de operaciones de seguridad", prompt: "Diseñá un dashboard de ciberseguridad / SOC, estilo control-room oscuro (#080B12) con verde matriz (#39FF88) y rojo crítico. Header con amenazas activas, incidentes, endpoints protegidos y nivel de riesgo. Mapa mundial de ataques con líneas de origen, feed de eventos de seguridad en vivo, gráfico de amenazas por severidad, y gauge de postura de seguridad. Entregable: HTML + CSS con grid, mapa de ataques en SVG y log de eventos con timestamps." },
  { sector: "App", layout: "mobile", nombre: "Feed Social Aurora", descripcion: "Feed vertical estilo Instagram con historias", prompt: "Diseña una pantalla de feed social para móvil (390x844) tipo Instagram con paleta violeta-magenta degradado y fondo oscuro casi negro (#0D0D14). Barra superior de historias circulares con anillo degradado, tarjetas de post con foto full-width, iconos de like/comentario/compartir en outline, y barra de navegación inferior con 5 iconos. Tipografía sans geométrica. Entregable: HTML+CSS autocontenido, mobile-first." },
  { sector: "App", layout: "chat", nombre: "Chat Mensajería Neo", descripcion: "Conversación 1 a 1 con burbujas", prompt: "Diseña una pantalla de chat 1 a 1 para móvil estilo WhatsApp/Telegram, paleta verde teal (#128C7E) sobre fondo crema con patrón sutil. Burbujas de mensaje diferenciadas (enviado verde a la derecha, recibido blanco a la izquierda), timestamps, ticks de leído azules, header con avatar y estado 'en línea', barra inferior con input, clip y micrófono. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "mobile", nombre: "Banca Saldo Zafiro", descripcion: "Dashboard bancario con tarjeta virtual", prompt: "Diseña el home de una app de banca digital para móvil, paleta azul zafiro y blanco con acentos verde lima, estilo fintech limpio (Revolut/N26). Tarjeta de crédito virtual en glassmorphism arriba, saldo grande, botones rápidos de enviar/recibir/recargar en fila, lista de transacciones recientes con iconos por categoría y montos coloreados. Entregable: HTML+CSS autocontenido mobile-first." },
  { sector: "App", layout: "mobile", nombre: "Fitness Ritmo Neón", descripcion: "Resumen de entrenamiento con anillos", prompt: "Diseña la pantalla de resumen diario de una app de fitness para móvil, fondo oscuro grafito con acentos verde neón y coral, estilo Apple Fitness. Anillos de actividad concéntricos animados en el centro, tarjetas de métricas (pasos, calorías, frecuencia cardíaca) con mini-gráficos, botón CTA 'Iniciar entrenamiento'. Tipografía condensada bold. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "list", nombre: "Delivery Menú Mango", descripcion: "Listado de platos de restaurante", prompt: "Diseña una pantalla de listado de platos de una app de delivery de comida para móvil, paleta naranja mango y blanco cálido, estilo Rappi/UberEats. Header con foto del restaurante y rating, chips de categorías scrollables, lista de platos con foto miniatura a la izquierda, nombre, descripción, precio y botón + para agregar. Barra inferior con carrito y total. Entregable: HTML+CSS autocontenido mobile." },
  { sector: "App", layout: "mobile", nombre: "Música Reproductor Vinilo", descripcion: "Pantalla now playing inmersiva", prompt: "Diseña la pantalla 'now playing' de una app de música para móvil, fondo con degradado extraído del arte del álbum (púrpura a durazno), estilo Spotify premium. Carátula grande con sombra, título de canción y artista, barra de progreso con scrubber, controles de reproducción centrados, botones de shuffle/repeat/corazón, y ecualizador visual sutil abajo. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "mobile", nombre: "Meditación Calma Salvia", descripcion: "Home de mindfulness sereno", prompt: "Diseña el home de una app de meditación para móvil, paleta salvia verde suave, beige y lavanda con degradados orgánicos, estilo Calm/Headspace. Saludo personalizado, tarjeta destacada 'Meditación del día' con ilustración de montañas, cuadrícula de categorías (Sueño, Ansiedad, Foco) con iconos redondeados, reproductor de sonido ambiente minimizado abajo. Tipografía serif suave. Entregable: HTML+CSS autocontenido mobile." },
  { sector: "App", layout: "list", nombre: "Tareas Foco Índigo", descripcion: "Lista de pendientes por proyecto", prompt: "Diseña una pantalla de lista de tareas para móvil, paleta índigo y blanco con acentos ámbar, estilo Todoist/Things minimalista. Encabezado 'Hoy' con contador, tareas agrupadas por sección con checkbox circular, etiquetas de proyecto en color, indicador de prioridad con banderita, fecha de vencimiento, y botón flotante + para añadir. Swipe hints visibles. Entregable: HTML+CSS autocontenido mobile-first." },
  { sector: "App", layout: "mobile", nombre: "Viajes Destino Coral", descripcion: "Detalle de destino turístico", prompt: "Diseña la pantalla de detalle de un destino de viaje para móvil, paleta turquesa océano y coral cálido, estilo Airbnb/Hopper. Foto hero full-bleed de playa con overlay degradado, título del destino y rating con estrellas, chips de clima y precio, sección de galería horizontal, descripción y botón CTA 'Reservar vuelo'. Barra de navegación translúcida. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "mobile", nombre: "E-commerce Producto Ónix", descripcion: "Ficha de producto de moda", prompt: "Diseña la ficha de producto de una app de e-commerce de moda para móvil, paleta negro ónix, blanco y un acento mostaza, estilo premium tipo Zara/SSENSE. Foto de producto grande con carrusel de puntos, nombre, precio, selector de talla en píldoras, selector de color en círculos, sección de reseñas resumida, y barra inferior fija con 'Añadir al carrito' y corazón de favorito. Entregable: HTML+CSS autocontenido mobile." },
  { sector: "App", layout: "list", nombre: "Citas Descubrir Rubí", descripcion: "Lista de matches y likes", prompt: "Diseña una pantalla de 'Me gusta' de una app de citas para móvil, paleta rubí rosado y púrpura con degradados cálidos, estilo Tinder/Bumble. Cuadrícula de dos columnas con fotos de perfiles, nombre y edad sobre overlay degradado, badge de 'Nuevo match', filtro superior de distancia, y barra inferior con iconos de descubrir/likes/chats/perfil. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "list", nombre: "Noticias Titulares Pizarra", descripcion: "Feed de noticias editorial", prompt: "Diseña un feed de noticias para móvil, paleta pizarra oscuro, blanco y rojo periodístico de acento, estilo NYT/Apple News editorial. Historia destacada con foto grande y titular serif bold, seguida de lista de artículos con miniatura a la derecha, categoría en mayúsculas, tiempo de lectura y hora. Barra superior con secciones scrollables. Tipografía serif para titulares, sans para cuerpo. Entregable: HTML+CSS autocontenido mobile." },
  { sector: "App", layout: "chat", nombre: "Soporte Bot Ártico", descripcion: "Chat con asistente de ayuda", prompt: "Diseña una pantalla de chat de soporte con asistente virtual para móvil, paleta azul ártico y blanco limpio, estilo Intercom. Burbujas del bot con avatar circular y botones de respuesta rápida (quick replies) en píldoras, burbujas del usuario en azul a la derecha, indicador 'escribiendo...' con tres puntos, header con nombre del asistente y estado, input inferior con adjuntar. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "mobile", nombre: "Feed Video Vertical Cobalto", descripcion: "Pantalla estilo reels/TikTok", prompt: "Diseña una pantalla de video vertical full-screen estilo TikTok/Reels para móvil, fondo del video con overlay oscuro inferior, acentos blanco y cobalto. Barra lateral derecha de acciones (avatar seguir, corazón con conteo, comentarios, compartir, disco giratorio de música), texto de caption y hashtags abajo a la izquierda, barra superior con pestañas 'Siguiendo/Para ti'. Entregable: HTML+CSS autocontenido mobile." },
  { sector: "App", layout: "mobile", nombre: "Banca Transferencia Menta", descripcion: "Flujo de envío de dinero", prompt: "Diseña una pantalla de transferencia de dinero de una app bancaria para móvil, paleta verde menta y azul marino, estilo fintech confiable. Campo de monto grande centrado con teclado numérico personalizado abajo, avatar y nombre del destinatario arriba, selector de cuenta origen, campo de concepto opcional, y botón CTA 'Enviar' prominente. Micro-copy de comisión cero. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "list", nombre: "Fitness Rutinas Grafito", descripcion: "Biblioteca de entrenamientos", prompt: "Diseña una lista de rutinas de entrenamiento para móvil, paleta grafito oscuro con acento amarillo eléctrico, estilo Nike Training Club. Tarjetas de rutina apiladas con foto de fondo, nombre del entrenamiento, duración, nivel de dificultad con barras, e icono de músculo trabajado. Filtros superiores en chips (Fuerza, Cardio, Yoga), barra de búsqueda. Entregable: HTML+CSS autocontenido mobile-first." },
  { sector: "App", layout: "mobile", nombre: "Delivery Seguimiento Fuego", descripcion: "Tracking de pedido en curso", prompt: "Diseña la pantalla de seguimiento de pedido de una app de delivery para móvil, paleta rojo fuego y blanco con mapa de fondo. Mapa con ruta del repartidor y pin animado en la parte superior (60% de pantalla), tarjeta inferior deslizable con estado 'En camino', tiempo estimado grande, barra de progreso por etapas (Preparando/Recogido/En camino/Entregado), datos del repartidor con foto y botón de llamar. Entregable: HTML+CSS autocontenido mobile." },
  { sector: "App", layout: "list", nombre: "Música Playlist Esmeralda", descripcion: "Detalle de lista de reproducción", prompt: "Diseña la pantalla de detalle de playlist de una app de música para móvil, paleta verde esmeralda profundo con degradado a negro, estilo Spotify. Portada de playlist grande arriba con título, autor y duración total, botones de reproducir (verde grande) y shuffle, lista de canciones con número, título, artista, duración y menú de tres puntos. Header colapsable. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "mobile", nombre: "Meditación Sesión Nocturna", descripcion: "Reproductor de sonido para dormir", prompt: "Diseña un reproductor de sesión de sueño de una app de meditación para móvil, paleta azul noche profundo con estrellas sutiles y acento dorado tenue, estilo Calm modo noche. Ilustración de paisaje nocturno con luna, título de la sesión 'Lluvia suave', temporizador circular de progreso, controles de play/pausa y rewind 15s, slider de volumen y selector de tiempo (15/30/60 min). Entregable: HTML+CSS autocontenido mobile." },
  { sector: "App", layout: "mobile", nombre: "Tareas Calendario Perla", descripcion: "Vista de agenda semanal", prompt: "Diseña una vista de agenda semanal de una app de productividad para móvil, paleta blanco perla, gris suave y acento coral, estilo Fantastical minimalista. Selector de días de la semana horizontal arriba con el día activo resaltado, timeline vertical con horas y bloques de eventos coloreados por categoría, indicador de 'ahora' con línea roja, botón flotante + para nuevo evento. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "mobile", nombre: "Viajes Itinerario Arena", descripcion: "Plan de viaje día por día", prompt: "Diseña una pantalla de itinerario de viaje día por día para móvil, paleta arena beige, terracota y verde oliva, estilo Wanderlog/TripIt cálido. Selector de días en pestañas, timeline vertical con paradas (hotel, actividad, restaurante) cada una con icono, hora, nombre y miniatura, líneas conectoras entre paradas, mapa colapsado arriba. Entregable: HTML+CSS autocontenido mobile-first." },
  { sector: "App", layout: "mobile", nombre: "E-commerce Carrito Lino", descripcion: "Resumen de carrito y checkout", prompt: "Diseña la pantalla de carrito de compras de una app de e-commerce para móvil, paleta blanco lino, negro y acento verde salvia, estilo minimalista escandinavo. Lista de productos con miniatura, nombre, variante, control de cantidad +/- y precio, sección de resumen con subtotal/envío/total, campo de código promocional, y botón fijo inferior 'Ir a pagar' con total. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "chat", nombre: "Citas Conversación Durazno", descripcion: "Chat entre match con perfil", prompt: "Diseña una pantalla de chat entre un match de app de citas para móvil, paleta durazno, rosa y crema con degradados suaves, estilo Hinge/Bumble cálido. Header con foto del match circular, nombre y botón de ver perfil, burbujas redondeadas (usuario en rosa, match en gris claro), sugerencias de rompehielos en chips arriba del input, input con emoji y GIF. Entregable: HTML+CSS autocontenido mobile." },
  { sector: "App", layout: "list", nombre: "Noticias Guardados Sepia", descripcion: "Artículos guardados para leer", prompt: "Diseña una pantalla de artículos guardados de una app de noticias para móvil, paleta sepia cálido, crema y marrón café, estilo Pocket/Instapaper para lectura. Lista de artículos guardados con miniatura cuadrada, titular serif, fuente, tiempo de lectura estimado y barra de progreso de lectura, filtro superior (Todos/No leídos/Favoritos), gesto de swipe para archivar. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "mobile", nombre: "Banca Presupuesto Turquesa", descripcion: "Análisis de gastos por categoría", prompt: "Diseña una pantalla de análisis de presupuesto de una app bancaria para móvil, paleta turquesa, blanco y acentos multicolor por categoría, estilo Monarch/YNAB. Gráfico de dona con gasto total en el centro, leyenda de categorías con porcentaje y monto, barra de progreso de presupuesto mensual, lista de categorías (Comida, Transporte, Ocio) con icono, barra de progreso y monto restante. Entregable: HTML+CSS autocontenido mobile." },
  { sector: "App", layout: "chat", nombre: "Grupo Chat Coral Vivo", descripcion: "Conversación grupal con reacciones", prompt: "Diseña una pantalla de chat grupal para móvil, paleta coral vivo y blanco con acentos azul, estilo Messenger/Slack móvil. Burbujas con nombre y mini-avatar del remitente para mensajes de otros, reacciones emoji flotantes bajo burbujas, mensaje con imagen adjunta en grid, indicador de varios escribiendo, header con avatares apilados del grupo y nombre. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "mobile", nombre: "Fitness Progreso Lima", descripcion: "Gráficos de evolución corporal", prompt: "Diseña una pantalla de progreso de fitness para móvil, paleta oscuro carbón con acento verde lima y magenta, estilo Whoop/Gymshark. Selector de métrica en pestañas (Peso, Fuerza, Medidas), gráfico de líneas grande con área degradada, tarjetas de récords personales, comparativa antes/después con fotos, resumen de racha semanal con llamas. Tipografía numérica bold. Entregable: HTML+CSS autocontenido mobile-first." },
  { sector: "App", layout: "list", nombre: "Delivery Restaurantes Sésamo", descripcion: "Descubrir restaurantes cercanos", prompt: "Diseña la pantalla de descubrimiento de restaurantes de una app de delivery para móvil, paleta blanco, negro sésamo y acento amarillo, estilo DoorDash. Barra de búsqueda con ubicación arriba, carrusel de categorías con iconos circulares (Pizza, Sushi, Burgers), lista de restaurantes con foto de portada, logo, nombre, rating, tiempo de entrega y costo de envío, badge de promoción. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "mobile", nombre: "Viajes Vuelo Boleto Cielo", descripcion: "Boarding pass digital", prompt: "Diseña un boarding pass digital de una app de viajes para móvil, paleta azul cielo y blanco con acento naranja, estilo aerolínea moderna. Tarjeta de boleto con recorte tipo ticket (borde festoneado), origen-destino con icono de avión y línea de ruta, hora de salida/llegada grandes, puerta, asiento y grupo de abordaje, código QR grande abajo, degradado de header con nombre del pasajero. Entregable: HTML+CSS autocontenido mobile." },
  { sector: "App", layout: "list", nombre: "Música Podcasts Ámbar", descripcion: "Lista de episodios de podcast", prompt: "Diseña una pantalla de detalle de podcast con episodios para móvil, paleta ámbar cálido, marrón oscuro y crema, estilo Overcast/Pocket Casts. Portada del podcast con nombre, autor y botón de suscribir, lista de episodios con fecha, título, descripción corta, duración, botón de play circular y progreso de escucha, controles de descarga. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "mobile", nombre: "E-commerce Home Arándano", descripcion: "Portada de tienda con ofertas", prompt: "Diseña el home de una app de e-commerce general para móvil, paleta arándano púrpura y blanco con acentos naranja de oferta, estilo Amazon/Mercado Libre moderno. Barra de búsqueda arriba, banner carrusel de promociones, cuadrícula de categorías con iconos, sección 'Ofertas relámpago' con temporizador y productos horizontales, cuadrícula de productos recomendados con precio tachado y descuento. Entregable: HTML+CSS autocontenido mobile." },
  { sector: "App", layout: "mobile", nombre: "Meditación Estadísticas Jade", descripcion: "Racha y progreso de práctica", prompt: "Diseña una pantalla de estadísticas de meditación para móvil, paleta jade verde suave, blanco y lavanda, estilo Headspace analítica calmada. Número de racha grande con icono de brote, calendario mensual con días meditados resaltados en círculos, tarjetas de minutos totales y sesiones completadas, gráfico de barras semanal de minutos, mensaje motivacional. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "list", nombre: "Tareas Bandeja Grafeno", descripcion: "Inbox de notificaciones y pendientes", prompt: "Diseña una bandeja de entrada de notificaciones y pendientes de una app de productividad para móvil, paleta gris grafeno oscuro con acentos azul eléctrico, estilo Superhuman/Linear móvil. Lista de items con icono de tipo (tarea, mención, recordatorio), título, snippet, tiempo relativo, punto de no leído, agrupados por 'Hoy' y 'Anterior', barra superior con filtros en segmentos. Entregable: HTML+CSS autocontenido mobile-first." },
  { sector: "App", layout: "mobile", nombre: "Noticias Detalle Marfil", descripcion: "Vista de lectura de artículo", prompt: "Diseña la vista de lectura de un artículo de noticias para móvil, paleta marfil crema, negro y acento azul enlace, estilo Medium/NYT lectura enfocada. Imagen de cabecera con crédito, titular serif grande, línea de autor con avatar y fecha, barra de progreso de lectura fija arriba, cuerpo con tipografía serif legible, cita destacada (pull quote), y barra inferior flotante con guardar/compartir/tamaño de fuente. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "Componentes", layout: "cards3", nombre: "Precios SaaS Neón", descripcion: "Tres planes con toggle mensual/anual", prompt: "Diseña un componente de tabla de precios de 3 columnas para una plataforma SaaS de analítica, estilo dark tech con fondo grafito #0D1117 y acentos neón cian #22D3EE y violeta #A78BFA. Plan central destacado con badge 'Más popular', borde glow y elevación. Incluye toggle mensual/anual con ahorro del 20%, lista de features con checks, y CTA por plan. Entregable: HTML + CSS con variables de color y hover states." },
  { sector: "Componentes", layout: "form", nombre: "Login Fintech", descripcion: "Acceso con email y biometría", prompt: "Diseña un formulario de login para una app fintech de banca digital, estética limpia y confiable con blanco #FFFFFF, azul marino #1E3A5F y verde menta #34D399. Campos email y contraseña con validación inline, toggle de mostrar contraseña, botón 'Iniciar sesión con Face ID', recordarme y enlace de recuperación. Entregable: HTML + CSS responsive con estados de foco y error." },
  { sector: "Componentes", layout: "split", nombre: "Registro Split Editorial", descripcion: "Alta con panel visual lateral", prompt: "Diseña un componente de registro con layout dividido para una plataforma de cursos online, estilo editorial cálido con crema #FAF3E0, terracota #E07856 y marrón oscuro #3D2C29. Panel izquierdo con imagen de estudiantes y testimonio, panel derecho con formulario de nombre, email, contraseña y checkbox de términos. Entregable: HTML + CSS con tipografía serif para títulos." },
  { sector: "Componentes", layout: "grid", nombre: "Cards Producto E-commerce", descripcion: "Grilla de tarjetas de producto", prompt: "Diseña una grilla de tarjetas de producto para un e-commerce de sneakers streetwear, estética bold urbana con negro #111111, amarillo eléctrico #FDE047 y gris claro #F3F4F6. Cada card con imagen, badge de descuento, nombre, precio tachado, rating de estrellas y botón 'Agregar al carrito' en hover. Entregable: HTML + CSS grid responsive de 4 columnas con animaciones sutiles." },
  { sector: "Componentes", layout: "split", nombre: "Navbar SaaS Mega", descripcion: "Barra con mega menú desplegable", prompt: "Diseña un componente de navbar con mega menú para una suite de productividad B2B, estilo corporativo moderno con blanco #FFFFFF, índigo #4F46E5 y slate #64748B. Logo a la izquierda, links con dropdown de productos en columnas con iconos y descripciones, buscador y botones 'Ingresar' y 'Prueba gratis'. Entregable: HTML + CSS con mega menú posicionado y sticky on scroll." },
  { sector: "Componentes", layout: "grid", nombre: "Footer Multicolumna Tech", descripcion: "Pie de página con newsletter", prompt: "Diseña un componente de footer de 4 columnas para una startup de infraestructura cloud, estética dark profesional con fondo #0F172A, texto gris #94A3B8 y acento verde lima #84CC16. Columnas de Producto, Empresa, Recursos y Legal, más bloque de suscripción a newsletter con input y botón, íconos sociales y selector de idioma. Entregable: HTML + CSS grid responsive." },
  { sector: "Componentes", layout: "form", nombre: "Modal Confirmación Borrado", descripcion: "Diálogo destructivo con overlay", prompt: "Diseña un componente modal de confirmación de acción destructiva para un panel de administración, estilo minimalista con blanco #FFFFFF, rojo alerta #EF4444 y gris neutro #6B7280. Overlay oscuro semitransparente, ícono de advertencia, título 'Eliminar proyecto', texto explicativo, campo para escribir el nombre a confirmar y botones 'Cancelar' y 'Eliminar'. Entregable: HTML + CSS con backdrop blur y animación de entrada." },
  { sector: "Componentes", layout: "grid", nombre: "Tabla de Datos Admin", descripcion: "Datatable con filtros y paginación", prompt: "Diseña un componente de tabla de datos para un dashboard de gestión de pedidos logísticos, estética funcional clara con blanco #FFFFFF, azul #2563EB y verde/rojo de estado. Encabezados ordenables, filas con checkbox de selección, badges de estado (Entregado, En tránsito, Cancelado), buscador, filtros por columna, acciones por fila y paginación inferior. Entregable: HTML + CSS con sticky header y hover de fila." },
  { sector: "Componentes", layout: "grid", nombre: "Calendario Reservas", descripcion: "Vista mensual con eventos", prompt: "Diseña un componente de calendario de reservas para una app de coworking, estilo suave y moderno con blanco roto #FAFAFA, morado #7C3AED y coral #FB7185. Vista de mes con celdas de día, indicadores de eventos por color, día actual resaltado, navegación entre meses y mini leyenda de tipos de reserva. Entregable: HTML + CSS grid de 7 columnas responsive." },
  { sector: "Componentes", layout: "split", nombre: "Timeline Historia Marca", descripcion: "Línea de tiempo vertical alterna", prompt: "Diseña un componente de timeline vertical alternado para la sección 'Nuestra historia' de una bodega de vino artesanal, estética elegante con fondo borgoña oscuro #4A1420, dorado #D4AF37 y crema #F5EBDD. Cada hito con año, título, descripción e imagen circular, conectados por línea central con nodos. Entregable: HTML + CSS con animación de aparición al hacer scroll." },
  { sector: "Componentes", layout: "cards3", nombre: "Testimonios Trío", descripcion: "Tres reseñas con avatar y rating", prompt: "Diseña un componente de testimonios de 3 tarjetas para una agencia de marketing digital, estilo fresco y confiable con blanco #FFFFFF, azul cielo #0EA5E9 y amarillo suave #FCD34D. Cada card con comillas grandes, texto de reseña, avatar, nombre, cargo, logo de empresa y 5 estrellas. Entregable: HTML + CSS con tarjeta central elevada." },
  { sector: "Componentes", layout: "grid", nombre: "FAQ Acordeón", descripcion: "Preguntas frecuentes expandibles", prompt: "Diseña un componente de FAQ tipo acordeón en dos columnas para una plataforma de seguros de salud, estética limpia y accesible con blanco #FFFFFF, teal #0D9488 y gris carbón #374151. Cada item con pregunta, ícono +/− que rota, y respuesta desplegable con transición de altura. Incluye buscador de preguntas arriba. Entregable: HTML + CSS con estados abierto/cerrado accesibles." },
  { sector: "Componentes", layout: "split", nombre: "Hero Features Producto", descripcion: "Encabezado con demo y beneficios", prompt: "Diseña un componente hero de features con layout dividido para una app de gestión de finanzas personales, estilo vibrante amigable con fondo degradado violeta a fucsia #7C3AED a #EC4899 y blanco. Lado izquierdo con titular potente, subtítulo, dos CTA y prueba social; lado derecho con mockup de la app flotando y tarjetas de features glassmorphism. Entregable: HTML + CSS con degradado y sombras suaves." },
  { sector: "Componentes", layout: "form", nombre: "Checkout Un Paso", descripcion: "Pago con resumen de orden", prompt: "Diseña un componente de checkout de una sola página para una tienda de café de especialidad, estética cálida artesanal con crema #F3E9DC, verde oliva #556B2F y marrón espresso #4B2E2E. Columna izquierda con datos de envío y método de pago con tarjetas de opción; columna derecha con resumen de orden sticky, cupón y total. Entregable: HTML + CSS de dos columnas responsive." },
  { sector: "Componentes", layout: "cards3", nombre: "Precios Agencia", descripcion: "Planes de servicio para agencias", prompt: "Diseña una tabla de precios de 3 columnas para una agencia de diseño web freelance, estilo bold minimalista con negro #0A0A0A, blanco #FFFFFF y naranja #FF6B35 de acento. Planes Básico, Pro y Enterprise con precio grande, descripción de servicios, features diferenciadas y CTA. Plan Pro resaltado con fondo invertido negro. Entregable: HTML + CSS con contraste alto." },
  { sector: "Componentes", layout: "form", nombre: "Formulario Multipaso", descripcion: "Wizard con barra de progreso", prompt: "Diseña un componente de formulario multipaso (wizard) para el onboarding de una plataforma de reclutamiento, estética profesional moderna con blanco #FFFFFF, azul eléctrico #3B82F6 y verde éxito #22C55E. Barra de progreso con 4 pasos numerados, campos del paso actual, y botones 'Atrás' y 'Siguiente'. Entregable: HTML + CSS mostrando el paso 2 activo con validación." },
  { sector: "Componentes", layout: "grid", nombre: "Cards Blog Revista", descripcion: "Grilla de artículos con categoría", prompt: "Diseña una grilla de tarjetas de artículos de blog para una revista de viajes, estilo editorial fotográfico con blanco #FFFFFF, negro #1A1A1A y turquesa #06B6D4 de acento. Cada card con imagen de portada, etiqueta de categoría, título, extracto, autor con avatar y tiempo de lectura. Entregable: HTML + CSS grid de 3 columnas con card destacada ancha arriba." },
  { sector: "Componentes", layout: "split", nombre: "Login Ilustrado Gaming", descripcion: "Acceso con arte 3D lateral", prompt: "Diseña un componente de login con panel ilustrado para una plataforma gamer de torneos, estética neón gaming con fondo negro azulado #0B1026, magenta #F026A3 y cian #16E0FF. Panel izquierdo con arte 3D abstracto y glow; panel derecho con formulario, login social (Discord, Steam, Google) y toggle de idioma. Entregable: HTML + CSS con efectos glow y bordes neón." },
  { sector: "Componentes", layout: "grid", nombre: "Bento Features Grid", descripcion: "Rejilla bento de características", prompt: "Diseña un componente bento grid de features para una herramienta de IA para escritura, estilo moderno tech con fondo casi negro #121212, blanco y acento verde neón #A3E635. Celdas de distinto tamaño combinando texto, íconos, mini gráficos y una celda destacada grande con animación. Entregable: HTML + CSS grid asimétrico responsive con hover en cada celda." },
  { sector: "Componentes", layout: "form", nombre: "Registro Newsletter Inline", descripcion: "Suscripción con incentivo", prompt: "Diseña un componente de registro a newsletter inline para un blog de tecnología, estética limpia y directa con blanco #FFFFFF, azul índigo #6366F1 y gris claro #E5E7EB. Bloque centrado con ícono de sobre, titular, subtítulo con incentivo (ebook gratis), input de email horizontal con botón 'Suscribirme' y nota de privacidad. Entregable: HTML + CSS con estado de éxito tras enviar." },
  { sector: "Componentes", layout: "cards3", nombre: "Equipo Tres Miembros", descripcion: "Tarjetas de perfil del equipo", prompt: "Diseña un componente de tarjetas de equipo (3 personas) para la página 'Nosotros' de un estudio de arquitectura, estilo minimalista sofisticado con blanco #FAFAFA, negro #111111 y arena #C2B280. Cada card con foto en blanco y negro, nombre, rol, bio corta e íconos sociales que aparecen en hover. Entregable: HTML + CSS con transición de color en la foto al pasar el mouse." },
  { sector: "Componentes", layout: "grid", nombre: "Dashboard Stats Cards", descripcion: "KPIs con mini gráficos", prompt: "Diseña un componente de tarjetas de estadísticas (KPI) para un dashboard de e-commerce, estética clean data con blanco #FFFFFF, azul #2563EB, verde #10B981 y rojo #EF4444. Cuatro cards con título de métrica, valor grande, variación porcentual con flecha coloreada y sparkline. Entregable: HTML + CSS grid de 4 columnas responsive con SVG de mini gráfico." },
  { sector: "Componentes", layout: "split", nombre: "Modal Video Onboarding", descripcion: "Popup con video y pasos", prompt: "Diseña un componente modal de bienvenida con video para una app de meditación, estética calma con fondo lavanda #E9E4F0, morado suave #9F7AEA y blanco. Layout dividido: izquierda video/ilustración con botón play, derecha título 'Bienvenido', lista de 3 beneficios y CTA 'Empezar'. Overlay con blur. Entregable: HTML + CSS con animación de escala al abrir." },
  { sector: "Componentes", layout: "grid", nombre: "Tabla Comparativa Planes", descripcion: "Matriz de features por plan", prompt: "Diseña un componente de tabla comparativa de features por plan para un software de gestión de proyectos, estilo corporativo claro con blanco #FFFFFF, azul acero #1E40AF y gris #9CA3AF. Filas de características agrupadas por categoría, columnas por plan con checks/cruces, columna destacada resaltada y CTA en el encabezado de cada plan. Entregable: HTML + CSS con header sticky." },
  { sector: "Componentes", layout: "form", nombre: "Formulario Contacto Mapa", descripcion: "Contacto con datos y mapa", prompt: "Diseña un componente de formulario de contacto para un restaurante de alta cocina, estética elegante oscura con fondo carbón #1C1C1C, dorado #C9A227 y blanco marfil #F8F4E3. Lado izquierdo con formulario (nombre, email, fecha de reserva, mensaje) y lado derecho con datos de contacto, horarios y mapa estilizado. Entregable: HTML + CSS de dos columnas con inputs con borde dorado." },
  { sector: "Componentes", layout: "cards3", nombre: "Pasos Cómo Funciona", descripcion: "Tres pasos numerados con íconos", prompt: "Diseña un componente 'Cómo funciona' de 3 pasos para una app de delivery de supermercado, estilo fresco y alegre con blanco #FFFFFF, verde brócoli #16A34A y naranja mandarina #F97316. Cada card con número grande de fondo, ícono ilustrado, título de paso y descripción, conectadas por flechas punteadas. Entregable: HTML + CSS con conectores entre tarjetas." },
  { sector: "Componentes", layout: "split", nombre: "Hero App Móvil", descripcion: "Encabezado con mockup de teléfono", prompt: "Diseña un componente hero dividido para el landing de una app de fitness, estética energética con fondo negro #0A0A0A, verde lima #BEF264 y gris oscuro. Izquierda con titular grande, subtítulo, botones de App Store y Google Play y badges de rating; derecha con mockup de iPhone mostrando la app y elementos flotantes de métricas. Entregable: HTML + CSS responsive con mockup en CSS." },
  { sector: "Componentes", layout: "grid", nombre: "Galería Portfolio Masonry", descripcion: "Grilla masonry de proyectos", prompt: "Diseña un componente de galería tipo masonry para el portfolio de un fotógrafo profesional, estilo minimal oscuro con fondo negro #0D0D0D, blanco y acento ámbar #F59E0B. Imágenes de distinta altura con overlay al hover mostrando título del proyecto y categoría, más filtros de categoría arriba. Entregable: HTML + CSS con columnas masonry y overlay de hover." },
  { sector: "Componentes", layout: "form", nombre: "Checkout Pago Tarjeta", descripcion: "Formulario de datos de tarjeta", prompt: "Diseña un componente de formulario de pago con tarjeta para una plataforma de streaming de música, estética moderna oscura con fondo #181818, verde #1DB954 y gris. Vista previa de tarjeta que actualiza en vivo con número, nombre y vencimiento; campos con máscaras, íconos de marca de tarjeta y botón 'Pagar $9.99'. Entregable: HTML + CSS con card preview animada y validación." },
  { sector: "Componentes", layout: "cards3", nombre: "Precios Freemium App", descripcion: "Free, Plus y Pro con features", prompt: "Diseña una tabla de precios de 3 planes para una app de notas y productividad, estilo suave pastel con blanco #FFFFFF, azul lavanda #818CF8 y rosa suave #FBCFE8. Planes Free, Plus y Pro con ícono ilustrado por plan, precio, lista de features con checks coloreados y CTA. Plan Plus destacado con degradado sutil. Entregable: HTML + CSS con tarjetas redondeadas y sombras suaves." },
  { sector: "Componentes", layout: "grid", nombre: "Logos Confían en Nosotros", descripcion: "Grilla de logos de clientes", prompt: "Diseña un componente de grilla de logos de clientes para una consultora tecnológica B2B, estética sobria profesional con blanco #FFFFFF, gris antracita #374151 y azul corporativo #2563EB. Titular 'Empresas que confían en nosotros', grilla de 6 a 8 logos en escala de grises que pasan a color en hover y una métrica destacada abajo. Entregable: HTML + CSS grid responsive con transición de opacidad." },
  { sector: "Componentes", layout: "split", nombre: "Timeline Proceso Horizontal", descripcion: "Etapas de proyecto en horizontal", prompt: "Diseña un componente de timeline horizontal de proceso para una agencia de branding, estilo moderno con fondo blanco #FFFFFF, negro #111827 y coral vibrante #FF5A5F. Cuatro etapas (Descubrimiento, Estrategia, Diseño, Lanzamiento) con nodos sobre una línea, número, título y descripción, etapa activa resaltada. Entregable: HTML + CSS con línea de progreso y responsive a vertical en móvil." },
  { sector: "Componentes", layout: "form", nombre: "Búsqueda Filtros Avanzados", descripcion: "Panel de búsqueda con facetas", prompt: "Diseña un componente de barra de búsqueda con panel de filtros avanzados para un marketplace inmobiliario, estética limpia con blanco #FFFFFF, azul océano #0369A1 y verde #059669. Input principal de ubicación, filtros de tipo, rango de precio con slider, dormitorios, checkboxes de amenidades y botón 'Buscar' con contador de resultados. Entregable: HTML + CSS con panel desplegable y chips de filtros activos." },
  { sector: "Componentes", layout: "cards3", nombre: "Casos de Éxito Trío", descripcion: "Tres cards con métrica destacada", prompt: "Diseña un componente de casos de éxito de 3 tarjetas para una plataforma SaaS de ventas B2B, estilo corporativo confiable con blanco #FFFFFF, azul profundo #1D4ED8 y verde métrica #16A34A. Cada card con logo del cliente, métrica grande destacada (+40% ventas), descripción breve del resultado y enlace 'Ver caso'. Entregable: HTML + CSS con número animado y hover de elevación." },
  { sector: "3D", layout: "scene3d", nombre: "Hero Zapatilla Deportiva", descripcion: "Zapatilla flotante que gira ante scroll", prompt: "Construí con Three.js un hero 3D full-screen para una marca de sneakers streetwear: una zapatilla en modelo GLTF flotando sobre un pedestal circular, iluminación de estudio con tres luces (key, fill, rim magenta), rotación automática suave y control por drag del usuario. Paleta negro carbón #0d0d0d con acentos volt #d0ff14 y magenta #ff2d78. Titular gigante 'AIRFLOW 24' con la cámara haciendo dolly al hacer scroll. Entregable: HTML+CSS+JS con Three.js (OrbitControls, GLTFLoader), sombras de contacto y bloom via EffectComposer." },
  { sector: "3D", layout: "scene3d", nombre: "Planeta Habitable", descripcion: "Exoplaneta con atmósfera y nubes", prompt: "Creá con Three.js una escena espacial de un exoplaneta tipo super-Tierra: esfera con shader custom de continentes, capa de nubes en malla separada rotando a distinta velocidad, glow atmosférico con Fresnel y un sol lejano con lens flare. Fondo de campo estelar en Points. Paleta cian glacial #4dd0e1, ocre continental #c98a3b y azul profundo espacial #060a1f. Panel HUD lateral con datos ficticios del planeta (gravedad, temperatura). Entregable: HTML+JS con Three.js, ShaderMaterial para el Fresnel y controles de órbita limitados." },
  { sector: "3D", layout: "scene3d", nombre: "Partículas Interactivas", descripcion: "Nube de partículas que huye del mouse", prompt: "Desarrollá con Three.js un fondo de 50.000 partículas GPU en un BufferGeometry que reaccionan al cursor: las partículas cercanas al puntero se repelen y vuelven a su posición con easing elástico. Estilo tech-startup minimalista, partículas como puntos suaves aditivos. Paleta fondo casi negro #08090c, partículas degradado índigo #6366f1 a cian #22d3ee. Titular centrado 'Inteligencia que fluye'. Entregable: HTML+JS con Three.js, raycasting sobre un plano invisible para el mouse y animación con requestAnimationFrame; blending aditivo." },
  { sector: "3D", layout: "scene3d", nombre: "Configurador de Auto", descripcion: "Visualizador de color y llantas en vivo", prompt: "Armá con Three.js un visualizador de producto para un auto eléctrico de lujo: modelo 3D sobre plataforma reflectante, HDRI de estudio para reflejos realistas, botones para cambiar color de carrocería (paint metalizado con clearcoat) y estilo de llantas en tiempo real. Paleta showroom blanco #f5f5f7, gris grafito #2b2f36 y acento eléctrico #00e0b0. Cámara con auto-rotación pausable y zoom. Entregable: HTML+CSS+JS con Three.js (GLTFLoader, RGBELoader, MeshPhysicalMaterial), panel de UI flotante y sombra de contacto suave." },
  { sector: "3D", layout: "scene3d", nombre: "Terreno Procedural", descripcion: "Montañas generadas con ruido Perlin", prompt: "Generá con Three.js un terreno procedural infinito: plano subdividido deformado por ruido simplex en el vertex shader, con niebla de distancia y sobrevuelo lento de la cámara. Estilo synthwave retro-futurista, grilla wireframe brillante sobre relieve sólido. Paleta noche violeta #1a0b2e, crestas neón rosa #ff3d81 y horizonte naranja #ff9e00 con sol degradado. Entregable: HTML+JS con Three.js, ShaderMaterial con noise GLSL, FogExp2 y un plano de sol con shader de bandas. Bucle sin fin desplazando el offset del ruido." },
  { sector: "3D", layout: "scene3d", nombre: "Galería de Arte 3D", descripcion: "Sala virtual navegable con cuadros", prompt: "Construí con Three.js una galería 3D navegable en primera persona: sala rectangular con piso de madera, paredes claras y cuadros enmarcados con texturas, spotlights individuales por obra e info al acercarse. Estética museo contemporáneo minimalista. Paleta paredes hueso #efece4, piso roble #9c7a4d y acentos de luz cálida #ffd8a8. Movimiento con WASD y mirada con mouse (PointerLockControls). Entregable: HTML+JS con Three.js, PointerLockControls, SpotLight por cuadro y colisión simple contra paredes." },
  { sector: "3D", layout: "scene3d", nombre: "Texto 3D Cinético", descripcion: "Tipografía extruida que se ensambla", prompt: "Creá con Three.js una intro de marca con texto 3D extruido: la palabra 'NOVA' se ensambla desde fragmentos que vuelan y encajan, material cromado con environment map y bevel pronunciado. Estética agencia creativa premium. Paleta fondo grafito #14151a, metal espejo con tintes iridiscentes y acento coral #ff5e57. Reflejos de estudio y bloom en los bordes. Entregable: HTML+JS con Three.js (TextGeometry con FontLoader, MeshStandardMaterial metálico, EffectComposer + UnrealBloomPass), animación de ensamblaje con easing." },
  { sector: "3D", layout: "scene3d", nombre: "Sistema Solar Interactivo", descripcion: "Órbitas planetarias con datos clicables", prompt: "Desarrollá con Three.js un sistema solar interactivo educativo: Sol emisivo central y ocho planetas texturizados orbitando a velocidades reales relativas, con líneas de órbita tenues y anillos en Saturno. Al hacer clic en un planeta la cámara hace tween hasta él y muestra ficha de datos. Paleta espacio #030308, Sol dorado #ffb703 y órbitas gris azulado #3a4a63. Entregable: HTML+CSS+JS con Three.js, TextureLoader, tween de cámara, Points para el fondo estelar y controles de órbita." },
  { sector: "3D", layout: "scene3d", nombre: "Ondas Oceánicas", descripcion: "Malla de olas animadas por shader", prompt: "Armá con Three.js una superficie de olas generada por shader: plano de alta resolución con desplazamiento sinusoidal sumado (Gerstner waves) en el vertex shader, espuma en las crestas y reflejo del cielo. Estética serena tipo marca de bienestar. Paleta agua turquesa #1ca9a0 a azul profundo #0a3d5c, espuma #eafaf7 y cielo pastel #cfe8f0. Cámara en ángulo bajo con leve cabeceo. Entregable: HTML+JS con Three.js, ShaderMaterial con Gerstner GLSL, luz direccional y niebla; sin librerías extra." },
  { sector: "3D", layout: "scene3d", nombre: "Isla Low-Poly", descripcion: "Isla flotante estilizada con agua", prompt: "Generá con Three.js una isla flotante low-poly: terreno facetado con flat shading, árboles y rocas geométricas, cascada de partículas cayendo al vacío y agua de plano semitransparente animado. Estética juego móvil cozy. Paleta pasto #7cc576, arena #e8d5a2, agua #4fb0c6 y cielo lavanda #cdb4f0. Rotación orbital lenta automática. Entregable: HTML+JS con Three.js, geometrías con flatShading, instancing para vegetación, sombras y OrbitControls con auto-rotate." },
  { sector: "3D", layout: "scene3d", nombre: "Hero Frasco de Perfume", descripcion: "Vidrio refractivo sobre pedestal", prompt: "Construí con Three.js un hero 3D para perfume de lujo: frasco de vidrio con material de transmisión (refracción, roughness baja, IOR alto) sobre un pedestal de mármol, HDRI cálido para reflejos y partículas doradas flotando. Estética alta perfumería elegante. Paleta champán #e6c78a, ámbar #b5651d, negro terciopelo #100d0a. Rotación suave y titular serif 'NUIT D'OR'. Entregable: HTML+CSS+JS con Three.js, MeshPhysicalMaterial con transmission, RGBELoader, bloom sutil y Points dorados." },
  { sector: "3D", layout: "scene3d", nombre: "Agujero Negro", descripcion: "Disco de acreción con distorsión", prompt: "Creá con Three.js una escena de agujero negro: esfera negra central rodeada por un disco de acreción de partículas en espiral con blending aditivo naranja-blanco, halo de lente y campo estelar de fondo. Estética ciencia ficción cinematográfica. Paleta vacío #000000, disco incandescente #ff7b00 a #fff4d6 y estrellas frías #9fb8ff. Cámara orbitando lento. Entregable: HTML+JS con Three.js, Points animados en espiral, AdditiveBlending, UnrealBloomPass y OrbitControls; sin modelos externos." },
  { sector: "3D", layout: "scene3d", nombre: "Partículas forman Logo", descripcion: "Nube que converge en un símbolo", prompt: "Desarrollá con Three.js una animación donde miles de partículas dispersas convergen para formar el logotipo de una marca fintech y luego se disuelven en loop. Las posiciones objetivo se muestrean del contorno de un texto/SVG. Estética tech confiable y limpia. Paleta fondo #0b1020, partículas degradado verde menta #2ee6a6 a azul #3b82f6. Entregable: HTML+JS con Three.js, muestreo de puntos desde un canvas de texto, interpolación posición-inicial a posición-objetivo con easing y AdditiveBlending." },
  { sector: "3D", layout: "scene3d", nombre: "Configurador de Reloj", descripcion: "Reloj de lujo con materiales cambiables", prompt: "Armá con Three.js un visualizador de reloj de lujo: modelo con manecillas animadas en hora real, opciones para cambiar material de caja (oro, acero, titanio) y color de correa, iluminación de joyería con reflejos nítidos. Estética relojería suiza premium. Paleta fondo antracita #1c1e22, oro #d4af37, acero #c8ccd0 y esfera azul medianoche #0f2a4a. Zoom y rotación controlados. Entregable: HTML+CSS+JS con Three.js (GLTFLoader o geometría propia, MeshPhysicalMaterial, HDRI), panel de opciones y tween de cámara a detalles." },
  { sector: "3D", layout: "scene3d", nombre: "Cordillera Wireframe", descripcion: "Relieve topográfico en líneas neón", prompt: "Generá con Three.js una cordillera topográfica en wireframe: malla montañosa por heightmap con ruido, renderizada solo en líneas brillantes con líneas de contorno de altura resaltadas y niebla profunda. Estética data-art / dashboard geoespacial. Paleta fondo azul noche #050d1a, líneas cian #17e0d0 y contornos ámbar #ffb02e en cotas altas. Cámara con órbita lenta cenital-oblicua. Entregable: HTML+JS con Three.js, WireframeGeometry o LineSegments, shader que colorea por altura, FogExp2 y OrbitControls." },
  { sector: "3D", layout: "scene3d", nombre: "Museo NFT Virtual", descripcion: "Pabellón oscuro con obras iluminadas", prompt: "Construí con Three.js un pabellón virtual para una colección NFT: sala oscura futurista con pedestales que exhiben obras 3D rotatorias sobre bases emisivas, reflejos en piso pulido y luces de neón perimetrales. Estética cripto-galería nocturna. Paleta negro #060608, piso espejo, neones violeta #8b5cf6 y cian #06d6f5. Navegación orbital entre pedestales. Entregable: HTML+JS con Three.js, MeshReflectorMaterial o plano reflectante, emisivos con bloom, PositionalAudio opcional y OrbitControls." },
  { sector: "3D", layout: "scene3d", nombre: "Tipografía Líquida", descripcion: "Letras que se derriten y rehacen", prompt: "Creá con Three.js un titular 3D con efecto líquido: la palabra 'FLOW' construida en metaballs / marching cubes que se derriten y vuelven a formarse en loop, material iridiscente tipo aceite. Estética editorial experimental de diseño. Paleta fondo crema #f3efe7, superficie tornasolada rosa-cian-violeta y sombra suave. Entregable: HTML+JS con Three.js usando MarchingCubes de examples/jsm, MeshPhysicalMaterial con iridescence, environment map y animación de campos metaball; rotación sutil." },
  { sector: "3D", layout: "scene3d", nombre: "Gigante Gaseoso", descripcion: "Planeta con anillos y lunas", prompt: "Desarrollá con Three.js un gigante gaseoso con anillos: esfera con shader de bandas atmosféricas en movimiento turbulento, sistema de anillos con transparencia y sombra proyectada sobre el planeta, dos lunas orbitando. Estética astronómica cinematográfica. Paleta bandas crema #e8d3a1 y siena #a5622f, anillos gris perla #cfc9bd, espacio #04060f. Cámara orbital lenta. Entregable: HTML+JS con Three.js, ShaderMaterial de bandas con noise, anillo con RingGeometry y textura alfa, Points estelares y OrbitControls." },
  { sector: "3D", layout: "scene3d", nombre: "Océano Realista", descripcion: "Agua PBR con cielo y reflejos", prompt: "Armá con Three.js un océano realista al atardecer usando el ejemplo Water + Sky: superficie con normal map animado, reflejos del cielo procedural con Sun controlable y horizonte infinito. Estética cinematográfica contemplativa. Paleta agua verde-azulada #2e6b6f, cielo durazno #ffb27a a lavanda #7b6ca8, sol dorado #ffd47e. Cámara con leve deriva. Entregable: HTML+JS con Three.js usando Water.js y Sky.js de examples/jsm, PMREMGenerator para el environment y animación del tiempo de las olas." },
  { sector: "3D", layout: "scene3d", nombre: "Ciudad Low-Poly", descripcion: "Metrópolis isométrica con tráfico", prompt: "Generá con Three.js una ciudad low-poly isométrica: bloques de edificios de alturas variadas con ventanas emisivas, autos como cajas moviéndose por avenidas en loop y ciclo día-noche que enciende luces. Estética diorama tech acogedor. Paleta día cielo #bfe3ff con edificios pastel, noche #10162e con ventanas ámbar #ffcf6b. Cámara orbital isométrica. Entregable: HTML+JS con Three.js, instancing para edificios y autos, luz direccional animada para el ciclo día-noche, emisivos con bloom y OrbitControls." },
  { sector: "3D", layout: "scene3d", nombre: "Hero Auriculares", descripcion: "Headphones con despiece animado", prompt: "Construí con Three.js un hero 3D para auriculares premium: el modelo se muestra armado y al hacer scroll hace un despiece (exploded view) separando cojines, driver y arco, con etiquetas de features apareciendo. Estética audio pro minimalista. Paleta fondo #0f1113, producto negro mate con acento cobre #c8794a y texto blanco. Iluminación de estudio suave. Entregable: HTML+CSS+JS con Three.js (GLTFLoader), animación de posiciones ligada al scroll, líneas guía a etiquetas HTML y sombra de contacto." },
  { sector: "3D", layout: "scene3d", nombre: "Salto al Hiperespacio", descripcion: "Warp de estrellas hacia la cámara", prompt: "Creá con Three.js un efecto de warp / hiperespacio: campo de estrellas como líneas estiradas que aceleran hacia el espectador con motion blur, culminando en un destello y un túnel de luz. Estética sci-fi intro de producto. Paleta espacio #02030a, estrellas blanco-azul #dbe7ff y núcleo del túnel cian eléctrico #22e0ff. Bucle con aceleración y desaceleración. Entregable: HTML+JS con Three.js, LineSegments o Points con estiramiento por velocidad, AfterimagePass para el motion blur y bloom; controles de velocidad." },
  { sector: "3D", layout: "scene3d", nombre: "Morphing GPGPU", descripcion: "Partículas que mutan entre formas", prompt: "Desarrollá con Three.js una escena de un millón de partículas que transicionan suavemente entre formas 3D (esfera, toro, cara, texto) usando simulación GPGPU en texturas de posición. Estética generativa de portafolio creativo. Paleta fondo #060608, partículas degradado según velocidad de rosa #ff4d9d a azul #4d7dff. Entregable: HTML+JS con Three.js usando GPUComputationRenderer, shaders de posición/velocidad, muestreo de vértices de geometrías objetivo y AdditiveBlending; botones para cambiar de forma." },
  { sector: "3D", layout: "scene3d", nombre: "Sneaker 360 E-commerce", descripcion: "Rotador de producto con hotspots", prompt: "Armá con Three.js un visor de producto 360 para ficha de e-commerce: zapatilla que el usuario rota con drag, hotspots clicables que abren tooltips de materiales, y botones de vista (superior, lateral, suela) que animan la cámara. Estética retail limpia y brillante. Paleta fondo blanco #ffffff con sombras suaves, producto en colorway azul cobalto #2b4de0 y detalles naranja #ff6a3d. Entregable: HTML+CSS+JS con Three.js (GLTFLoader), OrbitControls con límites, hotspots proyectados a 2D y tween de cámara a vistas predefinidas." },
  { sector: "3D", layout: "scene3d", nombre: "Metaballs Fluidas", descripcion: "Blobs orgánicos que se fusionan", prompt: "Generá con Three.js una escena de metaballs fluidas: esferas orgánicas que se atraen, fusionan y separan con superficie brillante tipo mercurio, flotando en un espacio con reflejos de environment. Estética marca de belleza / skincare futurista. Paleta fondo rosa nude #f6e7e1, superficie perlada con reflejos y acento coral #ff7f6b. Movimiento lento hipnótico. Entregable: HTML+JS con Three.js usando MarchingCubes de examples/jsm, MeshPhysicalMaterial con clearcoat, PMREM environment y física simple de atracción entre blobs." },
  { sector: "3D", layout: "scene3d", nombre: "Globo de Datos", descripcion: "Tierra con arcos de conexión animados", prompt: "Construí con Three.js un globo terráqueo de datos: esfera de la Tierra con textura de puntos (dot-matrix) y arcos luminosos animándose entre ciudades como flujos de datos globales, con puntos pulsantes en los nodos. Estética dashboard corporativo tech. Paleta fondo #070b18, globo azul acero #1e3a5f, arcos cian #33e1ff y nodos ámbar #ffc24d. Rotación automática pausable. Entregable: HTML+JS con Three.js, puntos sobre esfera vía muestreo, arcos como QuadraticBezierCurve3 animados con TubeGeometry o líneas, y OrbitControls con auto-rotate." },
  { sector: "Email", layout: "hero", nombre: "Newsletter Producto SaaS", descripcion: "Novedades mensuales de plataforma B2B", prompt: "Diseña un email HTML+CSS (tabla, ancho 600px, compatible con clientes de correo) para el newsletter mensual de un SaaS de gestión de proyectos. Hero superior con fondo azul índigo (#3730A3) degradado a violeta (#6D28D9), titular blanco 'Novedades de Julio' y captura de pantalla del producto con esquinas redondeadas. Debajo, tres bloques de features con icono lineal, título y un párrafo, cada uno con botón fantasma. Tipografía Inter, acentos en verde menta (#10B981), pie con enlaces de redes y baja. Entregable: un solo archivo .html inline-styled listo para enviar." },
  { sector: "Email", layout: "split", nombre: "Promo Moda Rebajas", descripcion: "Campaña de descuentos e-commerce", prompt: "Crea un email promocional HTML+CSS (600px, inline styles) para una tienda de moda femenina minimalista tipo Scandi. Layout split: mitad izquierda foto editorial de modelo, mitad derecha bloque crema (#F5F0E8) con titular serif 'Hasta -40%' en negro carbón, código VERANO40 en caja punteada y botón negro 'Comprar ahora'. Debajo, grilla de 3 productos con precio tachado. Paleta beige, negro y terracota (#C77B54). Tipografía Playfair Display + Helvetica. Entregable: .html responsive con media query para móvil apilando columnas." },
  { sector: "Email", layout: "hero", nombre: "Bienvenida App Fitness", descripcion: "Onboarding de nueva usuaria", prompt: "Diseña un email de bienvenida HTML+CSS (600px) para una app de entrenamiento en casa, tono enérgico y juvenil. Hero con fondo negro y foto atlética a sangre, titular condensado en amarillo neón (#D4FF00) '¡Empecemos!'. Bloque de 3 pasos numerados en círculos para configurar el perfil, cada uno con microcopy. CTA grande 'Abrir mi plan' en amarillo con texto negro. Barra de progreso decorativa 'Paso 1 de 3'. Tipografía Archivo. Entregable: archivo .html inline-styled con botones bulletproof VML para Outlook." },
  { sector: "Email", layout: "grid", nombre: "Digest Editorial Gastro", descripcion: "Recopilación semanal de recetas", prompt: "Crea un email newsletter HTML+CSS (600px) tipo revista para un blog de cocina de temporada, estético cálido y artesanal. Cabecera con logotipo servido y fecha. Grilla de 4 recetas en 2x2, cada tarjeta con foto cuadrada, categoría en versalitas, título serif y tiempo de preparación. Paleta crema (#FBF7F0), verde oliva (#5C6B3C) y mostaza (#D9A441). Sección lateral 'Ingrediente del mes'. Tipografía Fraunces + Karla. Entregable: .html responsive con grid que colapsa a una columna en móvil." },
  { sector: "Email", layout: "hero", nombre: "Promo Black Friday Tech", descripcion: "Oferta flash de electrónica", prompt: "Diseña un email de campaña Black Friday HTML+CSS (600px) para un e-commerce de gadgets tecnológicos, estilo dark y de alto impacto. Hero negro absoluto (#0A0A0A) con titular gigante glitch 'BLACK FRIDAY' en degradado cian-magenta y contador regresivo estático 'Termina en 48h'. Grilla de 4 productos destacados con badge de -50% rojo. CTA neón 'Ver ofertas'. Franja de urgencia 'Envío gratis hoy'. Tipografía Space Grotesk. Entregable: archivo .html inline con fallbacks para modo oscuro de clientes de correo." },
  { sector: "Email", layout: "split", nombre: "Bienvenida Membresía Premium", descripcion: "Alta en club de suscripción", prompt: "Crea un email de bienvenida HTML+CSS (600px) para una membresía premium de club de vinos, tono elegante y confidencial. Layout split: izquierda fondo burdeos profundo (#5B1A2B) con monograma dorado y 'Bienvenido al Club'; derecha fondo marfil con lista de 4 beneficios exclusivos marcados con serif dorada y botón 'Activar membresía' en dorado (#C9A24B). Sello circular 'Miembro fundador'. Tipografía Cormorant Garamond + Lato. Entregable: .html responsive que apila las mitades en móvil." },
  { sector: "Email", layout: "grid", nombre: "Newsletter Semanal Diseño", descripcion: "Curaduría de enlaces para creativos", prompt: "Diseña un email newsletter HTML+CSS (600px) editorial y tipográfico para una curaduría semanal de diseño y UX. Sin imágenes grandes: predomina texto. Cabecera con número de edición '#42' en display gigante. Lista de 6 enlaces curados, cada uno con número, título en negro, fuente en gris y descripción de una línea. Fondo blanco puro, acento único naranja quemado (#E8622C), separadores finos. Tipografía monoespaciada IBM Plex Mono para metadatos + Georgia para cuerpos. Entregable: archivo .html inline-styled, ligero y muy legible." },
  { sector: "Email", layout: "hero", nombre: "Lanzamiento Curso Online", descripcion: "Promo de inscripción a formación", prompt: "Crea un email promocional HTML+CSS (600px) para el lanzamiento de un curso online de ilustración digital, tono inspirador y colorido. Hero con fondo lavanda (#EDE7FB) e ilustración plana de escritorio creativo, titular 'Aprende a ilustrar en 6 semanas'. Bloque con foto de la instructora y bio breve. Lista de módulos con checks morados. CTA 'Reservar mi plaza' en morado (#7C3AED) con precio early-bird tachado. Prueba social con 2 testimonios. Tipografía Poppins. Entregable: .html responsive inline-styled." },
  { sector: "Email", layout: "split", nombre: "Confirmación de Pedido", descripcion: "Email transaccional de compra", prompt: "Diseña un email transaccional HTML+CSS (600px) de confirmación de pedido para una tienda de café de especialidad, limpio y funcional. Cabecera con check verde y '¡Gracias por tu pedido!'. Layout split del resumen: izquierda miniatura del producto, derecha detalles (cantidad, precio, número de orden #). Bloque de dirección de envío y estimado de entrega. Barra de estado del pedido en 4 etapas. Paleta blanco, marrón espresso (#3E2A20) y verde bosque. Tipografía DM Sans. Entregable: archivo .html inline-styled sin promociones intrusivas." },
  { sector: "Email", layout: "grid", nombre: "Newsletter Viajes Boutique", descripcion: "Destinos seleccionados del mes", prompt: "Crea un email newsletter HTML+CSS (600px) para una agencia de viajes boutique, estético aspiracional y cálido. Hero panorámico de paisaje con overlay y titular serif 'Escápate este otoño'. Grilla de 3 destinos, cada tarjeta con foto vertical, nombre del lugar, precio desde y botón 'Ver viaje'. Sección 'Consejo del viajero' en caja arena. Paleta arena (#E4D5C3), azul océano (#1E5F74) y coral (#E76F51). Tipografía Libre Baskerville + Nunito Sans. Entregable: .html responsive con grid que colapsa en móvil." },
  { sector: "Email", layout: "hero", nombre: "Digest Producto B2B", descripcion: "Resumen de métricas para clientes", prompt: "Diseña un email HTML+CSS (600px) de digest mensual para clientes de una plataforma de analítica de datos, tono profesional y sobrio. Hero claro con saludo personalizado y titular 'Tu resumen de julio'. Fila de 3 KPIs en tarjetas con número grande, etiqueta y flecha de tendencia verde/roja. Mini gráfico de barras dibujado con divs/tablas. Bloque 'Recomendación de la semana' con CTA 'Ver panel completo'. Paleta blanco, azul acero (#1D4ED8) y grises. Tipografía Inter. Entregable: archivo .html inline-styled sin dependencias de imágenes externas para las gráficas." },
  { sector: "Email", layout: "split", nombre: "Reactivación Carrito", descripcion: "Recordatorio de compra abandonada", prompt: "Crea un email de carrito abandonado HTML+CSS (600px) para una tienda de cosmética natural, tono amable y persuasivo. Layout split: izquierda foto del producto olvidado sobre fondo salvia, derecha texto '¿Se te olvidó algo?' con nombre y precio del artículo y botón 'Completar compra' en verde salvia (#87A96B). Franja de incentivo '-10% con código VUELVE10'. Bloque de 3 productos relacionados en miniatura. Paleta salvia, crema y rosa palo. Tipografía Marcellus + Mulish. Entregable: .html responsive inline-styled." },
  { sector: "Web", layout: "grid", nombre: "Portfolio Diseñador Gráfico", descripcion: "Vitrina de proyectos visuales", prompt: "Construye una página portfolio en HTML+CSS para un diseñador gráfico y de branding, estética editorial suiza. Cabecera fija minimal con nombre y menú. Grilla masonry de proyectos con imágenes que revelan título y categoría al hover con overlay. Paleta blanco roto (#FAFAF7), negro tinta y un acento rojo bermellón (#E63946). Tipografía Neue Haas / Helvetica en tamaños grandes, mucho espacio en blanco. Sección 'Sobre mí' de dos columnas y footer con email de contacto grande. Entregable: index.html + styles.css responsive con grid CSS y transiciones suaves." },
  { sector: "Web", layout: "split", nombre: "Portfolio Dev Full-Stack", descripcion: "Landing técnica de programador", prompt: "Construye una página portfolio en HTML+CSS para un desarrollador full-stack, estética dark de terminal moderna. Layout split en el hero: izquierda presentación 'Hola, soy Diego' con rol y stack, derecha bloque de código con sintaxis coloreada estático. Fondo gris carbón (#12141A), acentos verde terminal (#3FB950) y azul. Sección de proyectos en tarjetas con tags de tecnología, enlaces a GitHub y demo. Timeline de experiencia vertical. Tipografía JetBrains Mono para acentos + Inter para cuerpo. Entregable: index.html + styles.css responsive con modo oscuro por defecto." },
  { sector: "Web", layout: "hero", nombre: "Portfolio Fotógrafo", descripcion: "Galería inmersiva a pantalla completa", prompt: "Construye una página portfolio en HTML+CSS para un fotógrafo de retrato y paisaje, estética inmersiva y minimalista. Hero a pantalla completa con una fotografía a sangre, nombre del fotógrafo en tipografía fina superpuesta abajo y flecha de scroll. Al bajar, secciones full-bleed alternando foto grande y series con títulos sobrios. Paleta casi monocroma: negro, blanco y gris cálido, dejando que las fotos manden. Tipografía Cormorant en display ligero. Menú lateral discreto y contacto minimal. Entregable: index.html + styles.css responsive con scroll suave y lazy-load de imágenes." },
  { sector: "Web", layout: "split", nombre: "Currículum Web Interactivo", descripcion: "CV online de profesional", prompt: "Construye un currículum web en HTML+CSS para una profesional de marketing, estético limpio y confiable. Layout split de dos columnas fijas: barra lateral izquierda azul marino (#1B2A4A) con foto circular, datos de contacto, idiomas y barras de habilidades; columna derecha blanca con experiencia, formación y logros en formato timeline. Botón 'Descargar PDF' fijo. Acento dorado suave (#C9A24B). Tipografía Source Sans Pro. Impresión optimizada. Entregable: index.html + styles.css responsive que apila columnas en móvil y con estilos @media print." },
  { sector: "Web", layout: "hero", nombre: "Link-in-Bio Creador", descripcion: "Página de enlaces para redes", prompt: "Construye una página link-in-bio en HTML+CSS para un creador de contenido lifestyle, estética vibrante y mobile-first. Vista centrada tipo móvil: avatar circular, nombre con verificado, bio corta y una pila de botones-enlace grandes redondeados a sus plataformas, cada uno con icono. Fondo con degradado animado sutil coral a fucsia (#FF6B6B → #C44FE0). Botones glassmorphism semitransparentes. Iconos de redes al pie. Tipografía Poppins. Entregable: index.html + styles.css optimizado para pantalla vertical con hover y micro-animaciones." },
  { sector: "Web", layout: "grid", nombre: "Blog Personal Escritor", descripcion: "Revista personal de artículos", prompt: "Construye un blog personal en HTML+CSS para un escritor y ensayista, estética editorial cálida y lectora. Cabecera con nombre en serif grande y navegación por temas. Grilla de artículos: uno destacado ancho arriba y luego tres columnas con fecha, categoría, título y extracto. Paleta papel (#F4EFE6), tinta marrón oscuro y acento verde salvia. Tipografía Lora para titulares + Source Serif para cuerpo, con generoso interlineado. Sidebar con 'Sobre el autor' y suscripción al boletín. Entregable: index.html + styles.css responsive centrado en la legibilidad." },
  { sector: "Web", layout: "grid", nombre: "Portfolio Arquitecto", descripcion: "Catálogo de obras construidas", prompt: "Construye una página portfolio en HTML+CSS para un estudio de arquitectura, estética brutalista refinada. Cabecera con nombre del estudio en mayúsculas y línea divisoria. Grilla asimétrica de proyectos con fotografías arquitectónicas en blanco y negro, número de proyecto, nombre y año; al hover se revela la foto a color. Paleta hormigón: blanco, negro y gris cemento (#8C8C88), un único acento naranja constructivo (#F25C05). Tipografía Helvetica Neue condensada. Sección de filosofía y datos de contacto tabulados. Entregable: index.html + styles.css responsive con grid CSS asimétrico." },
  { sector: "Web", layout: "hero", nombre: "Portfolio Ilustrador", descripcion: "Muestrario colorido de ilustración", prompt: "Construye una página portfolio en HTML+CSS para un ilustrador editorial, estética juguetona y saturada. Hero con ilustración protagonista grande, nombre en tipografía redondeada custom y burbuja '¡Hola!'. Debajo, grilla irregular de ilustraciones con marcos que rotan levemente al hover. Fondo crema (#FFF8E7) con manchas de color de acento amarillo, cian y rosa. Sección de clientes con logos y bloque de contacto tipo nota adhesiva. Tipografía Fredoka + Nunito. Entregable: index.html + styles.css responsive con micro-animaciones lúdicas." },
  { sector: "Web", layout: "split", nombre: "Portfolio UX/UI", descripcion: "Casos de estudio de producto", prompt: "Construye una página portfolio en HTML+CSS para una diseñadora de producto UX/UI, estética clean SaaS. Hero split: izquierda titular 'Diseño experiencias que resuelven' con subrol y CTA 'Ver casos', derecha mockup de app flotante con sombra suave. Sección de casos de estudio en tarjetas grandes con imagen, problema, rol y métrica de impacto. Paleta blanco, azul eléctrico (#2563EB) y lila suave de fondo (#F1F0FB). Tipografía Inter con jerarquía marcada. Bloque de proceso en 4 pasos. Entregable: index.html + styles.css responsive con hover states y grid de casos." },
  { sector: "Web", layout: "hero", nombre: "Link-in-Bio Músico", descripcion: "Hub de lanzamientos y conciertos", prompt: "Construye una página link-in-bio en HTML+CSS para un músico independiente, estética nocturna y sonora. Hero vertical con foto del artista en duotono, nombre en display y último single destacado con botón 'Escuchar ahora'. Pila de enlaces a Spotify, YouTube, entradas y merch, cada uno con su icono de marca. Fondo negro azulado (#0D1B2A) con acentos púrpura neón (#9D4EDD) y ondas de audio decorativas. Lista de próximas fechas de gira. Tipografía Anton para titulares + Barlow. Entregable: index.html + styles.css mobile-first con efectos de brillo." },
  { sector: "Web", layout: "grid", nombre: "Blog Personal Tech", descripcion: "Bitácora de notas técnicas", prompt: "Construye un blog personal en HTML+CSS para un ingeniero de software, estética developer minimalista con soporte de modo claro/oscuro. Cabecera con handle, toggle de tema y navegación. Grilla de posts en lista con fecha monoespaciada, tiempo de lectura, título y tags de tecnología clicables. Bloques de código con resaltado estático. Paleta modo claro blanco/gris y acento verde azulado (#0D9488); modo oscuro fondo #0F172A. Tipografía Inter + Fira Code para código. Sección 'now' y links a proyectos. Entregable: index.html + styles.css responsive con variables CSS para ambos temas." },
  { sector: "Web", layout: "split", nombre: "Currículum Web Consultor", descripcion: "Perfil ejecutivo de alto nivel", prompt: "Construye un currículum web en HTML+CSS para un consultor estratégico senior, estética corporativa premium y sobria. Layout split: panel izquierdo fijo blanco con foto profesional, nombre, titular ejecutivo, contacto y sectores de especialidad; panel derecho con secciones de experiencia en firmas, logros cuantificados en cifras destacadas, formación y publicaciones. Paleta blanco, gris grafito (#2E2E2E) y acento verde botella (#14532D). Tipografía Libre Franklin con detalles serif. Botón 'Solicitar reunión' fijo. Entregable: index.html + styles.css responsive con estilos @media print para exportar a PDF." },
  { sector: "Juegos", layout: "grid", nombre: "Snake Neón Retro", descripcion: "Serpiente neón sobre grilla oscura", prompt: "Construí Snake en HTML5 canvas + JS puro sobre una grilla de 20x20 celdas. Estilo synthwave: fondo #0d0221, grilla con líneas #2d1b4e, serpiente con gradiente neón cian #05d9e8 a magenta #ff2a6d y estela con glow (shadowBlur). Manzana pixelada amarilla pulsante. HUD superior con puntaje y récord en fuente monospace. Controles WASD/flechas, velocidad creciente, game-over con overlay glitch. Entregable: index.html autocontenido con canvas y game loop en requestAnimationFrame." },
  { sector: "Juegos", layout: "grid", nombre: "Pong Arcade CRT", descripcion: "Pong con efecto tubo CRT", prompt: "Programá Pong clásico 2 jugadores en canvas + JS. Estética CRT ámbar sobre negro #000, paletas y pelota monocromas #ffb000 con scanlines y viñeta simulada por overlay CSS. Línea central punteada, marcador gigante tipo dígitos de siete segmentos dibujados a mano. Física de rebote con ángulo según punto de impacto, aceleración progresiva, IA opcional para P2. Sonido beep con WebAudio oscillator. Entregable: HTML+CSS+JS en un archivo, loop a 60fps." },
  { sector: "Juegos", layout: "grid", nombre: "Breakout Cristal", descripcion: "Rompe-ladrillos con ladrillos de vidrio", prompt: "Creá Breakout en canvas + JS con estética glassmorphism: fondo degradado azul #1e3a8a a violeta #6d28d9, ladrillos semitransparentes con blur y bordes brillantes en 6 filas de colores pastel. Bola con rastro de partículas, paleta con reflejo. Power-ups que caen (paleta ancha, multibola), contador de vidas con iconos corazón. Efecto de shake al romper filas. Entregable: index.html único con canvas, colisiones AABB y sistema de partículas." },
  { sector: "Juegos", layout: "grid", nombre: "Memoria Tropical", descripcion: "Cartas de frutas para emparejar", prompt: "Desarrollá un juego de Memoria en grilla 4x4 con HTML/CSS/JS (cartas como divs con flip 3D en CSS transform). Tema tropical: fondo verde selva #14532d, cartas con dorso patrón de hojas y frente con emojis de frutas grandes. Animación de volteo suave 0.5s, resaltado dorado al acertar par, contador de movimientos y cronómetro. Pantalla de victoria con confeti CSS. Entregable: archivo HTML autocontenido, lógica de matching y barajado Fisher-Yates." },
  { sector: "Juegos", layout: "grid", nombre: "Buscaminas Blueprint", descripcion: "Minesweeper estilo plano técnico", prompt: "Implementá Buscaminas 10x10 con HTML/CSS/JS renderizado en grilla de celdas. Estética blueprint: fondo azul cianotipo #0b3d91, líneas y números en blanco tipo plano de ingeniería, banderas como iconos de compás. Números de proximidad con paleta clásica (1 azul, 2 verde, 3 rojo) adaptada a alto contraste. Click izquierdo revela con flood-fill, click derecho bandera, timer y contador de minas. Entregable: index.html único, generación aleatoria de minas y reveal recursivo." },
  { sector: "Juegos", layout: "grid", nombre: "2048 Pastel", descripcion: "Fusión de números tonos pastel", prompt: "Construí 2048 en grilla 4x4 con HTML/CSS/JS. Paleta pastel suave: fondo #faf8ef, celdas vacías #cdc1b4, fichas desde #eee4da (2) escalando a naranjas y dorados con tipografía redondeada bold. Animaciones de deslizamiento y aparición con scale-pop via CSS transform. Marcador y mejor puntaje persistido en localStorage. Controles flechas y swipe táctil. Overlay 'Ganaste' al llegar a 2048 y 'Game Over'. Entregable: archivo HTML autocontenido con lógica de merge y spawn." },
  { sector: "Juegos", layout: "grid", nombre: "Tres en Raya Minimal", descripcion: "Tic-tac-toe monocromo elegante", prompt: "Creá Tic-tac-toe en grilla 3x3 con HTML/CSS/JS minimalista escandinavo: fondo #f5f5f4, líneas finas gris carbón #292524, X en coral #f87171 y O en teal #2dd4bf dibujadas con SVG stroke animado (draw-in). Modo 2 jugadores y modo IA con minimax imbatible seleccionable. Línea ganadora resaltada con trazo animado, marcador de partidas. Entregable: index.html único, minimax en JS y animaciones SVG." },
  { sector: "Juegos", layout: "grid", nombre: "Quiz Relámpago", descripcion: "Trivia con temporizador y streak", prompt: "Programá un Quiz de opción múltiple en HTML/CSS/JS con layout de tarjeta central y 4 respuestas en grilla 2x2. Estética vibrante estilo Kahoot: fondo degradado púrpura #7c3aed a rosa #ec4899, cada opción con color propio (rojo, azul, amarillo, verde) y forma geométrica. Barra de tiempo de 15s que se agota, feedback verde/rojo instantáneo, contador de racha y puntaje ponderado por rapidez. Banco de 10 preguntas en array JSON. Pantalla final con resultado. Entregable: archivo HTML autocontenido." },
  { sector: "Juegos", layout: "scene3d", nombre: "Ruleta de Premios 3D", descripcion: "Rueda giratoria con perspectiva", prompt: "Construí una Ruleta de la fortuna en canvas 2D con ilusión 3D (sombras y gradientes radiales). Estética casino dorado: fondo terciopelo #4a0e0e, aro dorado #d4af37 con luces LED que parpadean, 8 sectores de colores alternos con etiquetas de premio. Giro con física de fricción y desaceleración ease-out, puntero superior con rebote al cruzar topes. Efecto de brillo metálico y sonido tick por sector con WebAudio. Botón GIRAR pulsante. Entregable: index.html único con animación por requestAnimationFrame." },
  { sector: "Juegos", layout: "grid", nombre: "Tetris Vaporwave", descripcion: "Tetris simple estética vaporwave", prompt: "Desarrollá Tetris en canvas + JS sobre tablero 10x20. Estética vaporwave: fondo grid rosa/cian con sol retro, piezas tetromino con gradientes pastel #ff71ce, #01cdfe, #05ffa1 y bordes brillantes. Panel lateral con próxima pieza, puntaje, líneas y nivel. Rotación SRS básica, hard drop, aceleración por nivel, flash al completar líneas. Fuente pixel. Entregable: archivo HTML autocontenido con matriz de colisión y game loop temporizado." },
  { sector: "Juegos", layout: "scene3d", nombre: "Flappy Parallax", descripcion: "Ave con fondo de capas en profundidad", prompt: "Creá un clon de Flappy Bird en canvas + JS con parallax de múltiples capas dando sensación de profundidad. Estética atardecer: cielo degradado naranja #fb923c a púrpura #7c3aed, montañas y nubes en 3 capas a distinta velocidad, tuberías estilizadas verde menta. Ave con animación de aleteo y rotación según velocidad vertical. Física de gravedad y salto, puntaje por tubería, mejor marca en localStorage, pantalla de choque. Entregable: index.html único, generación procedural de obstáculos." },
  { sector: "Juegos", layout: "scene3d", nombre: "Reloj Orbital Creativo", descripcion: "Hora como órbitas planetarias 3D", prompt: "Construí un reloj creativo con Three.js donde horas, minutos y segundos son esferas orbitando un núcleo central en tres anillos concéntricos inclinados en el espacio 3D. Estética cósmica: fondo negro con estrellas, núcleo emisivo dorado, órbitas con líneas tenues, esferas con material metálico y bloom. La posición angular refleja la hora real actualizada cada frame; etiqueta digital flotante opcional. Cámara con leve auto-rotación. Entregable: index.html con Three.js por CDN, escena, luces y render loop." },
  { sector: "Juegos", layout: "scene3d", nombre: "Visualizador de Audio 3D", descripcion: "Barras reactivas al micrófono en 3D", prompt: "Programá un visualizador de audio con Three.js + Web Audio API AnalyserNode que reacciona al micrófono o a un archivo cargado. Estética neón: anillo circular de barras 3D que crecen con las frecuencias, color mapeado por banda (bajos rojo #ff2a6d, medios violeta, altos cian) con bloom y fondo oscuro reflectante. Rotación lenta de cámara, partículas que pulsan con el volumen. Botón para activar micrófono o subir MP3. Entregable: index.html con Three.js por CDN y FFT en tiempo real." },
  { sector: "Juegos", layout: "grid", nombre: "Simón Dice Luces", descripcion: "Memoria de secuencia con sonido", prompt: "Creá Simón (memoria de secuencia) con HTML/CSS/JS: cuatro cuadrantes de colores (verde, rojo, amarillo, azul) formando un círculo dividido, cada uno se ilumina y suena una nota WebAudio distinta. Estética retro-arcade con carcasa oscura #1a1a2e y botones con brillo al activarse. La secuencia crece un paso por ronda, el jugador la repite; error termina la partida mostrando la ronda alcanzada. Nivel de récord persistido. Entregable: archivo HTML autocontenido con temporización de reproducción." },
  { sector: "Juegos", layout: "grid", nombre: "Cuatro en Línea Fichas", descripcion: "Connect Four con caída animada", prompt: "Desarrollá Cuatro en Línea en grilla 7x6 con HTML/CSS/canvas. Estética tablero de madera azul #1d4ed8 con celdas circulares caladas, fichas rojas y amarillas que caen con animación de gravedad y rebote (easing bounce). Detección de victoria horizontal, vertical y diagonal con resaltado de las 4 fichas ganadoras. Modo 2 jugadores y IA por evaluación de tablero. Indicador de turno. Entregable: index.html único con animación de caída por requestAnimationFrame." },
  { sector: "Juegos", layout: "scene3d", nombre: "Asteroides Vectoriales", descripcion: "Nave espacial en campo de asteroides", prompt: "Construí Asteroids en canvas + JS con gráficos vectoriales estilo arcade Atari: fondo negro profundo, nave, asteroides y disparos como polígonos de trazo blanco con glow sutil, sensación de espacio abierto. Física inercial con wrap en los bordes, rotación y empuje de la nave, asteroides que se fragmentan al recibir impacto, sistema de puntaje y vidas. Explosiones de partículas vectoriales. Entregable: archivo HTML autocontenido, colisiones por distancia y game loop." },
  { sector: "Juegos", layout: "scene3d", nombre: "Corredor Infinito 3D", descripcion: "Endless runner con obstáculos en pista", prompt: "Programá un endless runner en Three.js: un cubo/personaje corre por una pista con tres carriles esquivando obstáculos que se acercan en profundidad. Estética low-poly vibrante: pista degradada, cielo pastel #a5b4fc, obstáculos y monedas geométricos con sombras. Cambio de carril con flechas, salto con espacio, velocidad creciente, puntaje por distancia y monedas recolectadas. Niebla al fondo para fade de spawn. Entregable: index.html con Three.js por CDN, generación procedural y detección de colisiones." },
  { sector: "Juegos", layout: "grid", nombre: "Topos al Ataque", descripcion: "Whack-a-mole con reflejos", prompt: "Creá Whack-a-mole en grilla 3x3 de agujeros con HTML/CSS/JS. Estética jardín cartoon: fondo verde césped, agujeros marrones, topos que asoman con animación pop-up y gorros graciosos. Aparecen aleatoriamente con ventana de tiempo decreciente; click o tap suma puntos y muestra golpe con partículas. Cuenta regresiva de 30s, combo por golpes seguidos, ranking en localStorage. Sonido de golpe WebAudio. Entregable: archivo HTML autocontenido con temporizadores y spawn aleatorio." },
  { sector: "Juegos", layout: "grid", nombre: "Sopa de Palabras", descripcion: "Wordle en español con teclado", prompt: "Desarrollá un clon de Wordle en español con HTML/CSS/JS: grilla 6x5 de casillas y teclado en pantalla en grilla QWERTY. Estética limpia clara: fondo #ffffff, casillas con borde gris que revelan verde #6aaa64 (correcta), amarillo #c9b458 (posición) y gris (ausente) con animación flip escalonada. Diccionario de palabras de 5 letras en array, validación de intento, shake si no existe, teclas coloreadas según feedback. Estadísticas de racha. Entregable: index.html único autocontenido." },
  { sector: "Juegos", layout: "grid", nombre: "Sudoku Diario", descripcion: "Sudoku 9x9 con notas y pistas", prompt: "Construí un Sudoku 9x9 con HTML/CSS/JS: grilla con subcuadros 3x3 de bordes gruesos, celdas fijas en negro y editables en azul #2563eb. Estética papel periódico crema #fdf6e3, resaltado de fila, columna y subcuadro de la celda activa, conflictos marcados en rojo. Teclado numérico, modo notas (candidatos pequeños), botón de pista y verificación. Generador con solución única por backtracking y niveles de dificultad. Timer. Entregable: archivo HTML autocontenido con solver." },
  { sector: "Juegos", layout: "grid", nombre: "Sokoban Almacén", descripcion: "Empuja cajas a sus destinos", prompt: "Programá Sokoban en grilla basada en tiles con HTML/CSS/canvas. Estética almacén industrial: fondo hormigón gris #3f3f46, cajas de madera con textura, destinos marcados con círculos amarillos que brillan al llenarse, personaje operario pixelado. El jugador empuja (no tira) cajas; una caja no se mueve si hay pared o caja detrás. 8 niveles definidos en mapas de texto ASCII, contador de movimientos, undo, detección de nivel resuelto. Entregable: index.html único con parser de niveles." },
  { sector: "Juegos", layout: "scene3d", nombre: "Cubo Rubik Interactivo", descripcion: "Rubik 3D girable y mezclable", prompt: "Creá un cubo de Rubik 3x3 interactivo con Three.js: 27 cubies con las seis caras de colores clásicos (blanco, amarillo, rojo, naranja, azul, verde) y bordes negros. Estética estudio limpio con fondo gris claro, iluminación suave y sombra de contacto. Rotación de la vista con arrastre (OrbitControls) y giro de caras por click-drag sobre una fila con animación suave de 90 grados. Botones mezclar y reset, contador de movimientos. Entregable: index.html con Three.js por CDN, lógica de rotación de capas y detección de resuelto." },
]
